window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-09"] = [
  { id: "cn--1885--m01", track: "cn", year: 1885, yearApprox: false, dim: "military", weight: 4, title: "镇南关、谅山之捷", summary: "冯子材守长墙却法军，清军复谅山。", detail: { background: "1884年秋以后法军由东京（越北）进犯广西边境，镇南关外师次关内，清廷以冯子材帮办广西军务，收合溃卒，筑长墙横岭以守。", process: "1885年3月下旬（光绪十一年二月初九前后，日期尚有朔换算之异）法军分路犯镇南关，冯子材亲当长墙，王孝祺、苏元春等部分援，相持两日，法军却；清军乘胜追击，3月底至4月初克谅山，法军统帅尼格里受创退守。法国内阁以是报更迭。", impact: "此为开战以来清军最大一次胜仗，而清廷已主「乘胜即收」，4月4日巴黎先订停战专条，前线接令罢兵，桂、滇诸军未复大进；论中法战事「疆场未败而约已成」者，每以镇南关、谅山为据。", figures: ["冯子材","苏元春","王孝祺"], place: "广西镇南关至谅山（今广西凭祥、越南谅山）", state: "清", sources: ["《清史稿·冯子材传》","中国近代史资料丛刊《中法战争》","《（光绪）东华录》"], tags: ["中法战争","镇南关","谅山"] }, related: ["cn--1884--m01", "cn--1885--p01"] },
  { id: "cn--1885--m02", track: "cn", year: 1885, yearApprox: false, dim: "military", weight: 2, title: "法军据澎湖与镇海之守", summary: "孤拔取澎湖为基，浙东镇海却之。", detail: { background: "法军既不得志于台湾北部，清廷以基隆、淡水相持经年，远东舰队须别取停泊之所。", process: "1885年3月初，法舰队司令孤拔率舰占澎湖列岛，毁其炮台，以为进退之基；3月下旬法舰犯浙江镇海，守将欧阳利见、薛福成筹防，岸炮击中旗舰，法军未能登岸。6月孤拔病殁于澎湖妈宫。", impact: "澎湖之失与福建、台湾之防同时暴露，1885年台湾建省后之善后诸议即缘此而发；镇海一隅得以无扰，然和约已定，法军仍留踞澎湖至当年始撤。", figures: ["孤拔","欧阳利见","薛福成"], place: "浙江镇海、福建澎湖", state: "清", sources: ["《清史稿·欧阳利见传》","中国近代史资料丛刊《中法战争》","马士《中华帝国对外关系史》卷二"], tags: ["中法战争","澎湖","海防"] }, related: ["cn--1885--m01", "cn--1885--i02"] },
  { id: "cn--1885--p01", track: "cn", year: 1885, yearApprox: false, dim: "politics", weight: 4, title: "中法订越南条约", summary: "李鸿章与巴德诺订约，越南属藩遂绝。", detail: { background: "镇南关之捷与巴黎停战专条几乎同时而至，清廷以军事未败而饷绌、和议已成，命李鸿章与法使续议条约。", process: "1885年6月9日（光绪十一年四月二十七日）李鸿章与法国公使巴德诺在天津签《中法会订越南条约》十款，清廷承认法国与越南所立之约、撤滇桂之戍，开云南两处边界通商，并规定日后中国若修铁路须向法国购办；同年7月换约。", impact: "越南之宗藩关系自约文而终，西南门户遂启；法国借通商、筑路诸款立日后干预之据，滇越铁路与两广矿务之案皆援此约。论清代藩属体制之解体者以1885年为一节点。", figures: ["李鸿章","巴德诺","载湉"], place: "天津", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（光绪）东华录》","马士《中华帝国对外关系史》卷二"], tags: ["中法新约","越南","宗藩"] }, related: ["cn--1883--p01", "cn--1885--m01"] },
  { id: "cn--1885--e01", track: "cn", year: 1885, yearApprox: false, dim: "economy", weight: 2, title: "轮船招商局归盛宣怀整顿", summary: "风潮之后，局务改归督办整顿。", detail: { background: "1883年上海金融风潮之后，招商局债台高垒、股值低落，局中用人、账务之弊并见，论者谓非改章无以自存。", process: "1885年李鸿章奏请将轮船招商局改归盛宣怀接办，秋间盛氏入局任督办，以局产抵偿洋债与官款，清造账目、裁并分局，并续借洋款以济流转；徐润、唐廷枢任事之局由是告终。", impact: "招商局免于停摆，而官督商办之权渐归督办一人，商股发言日轻；此后电报、铁路诸局皆循此格，论近代公司控制权之移转者每以1885年之改为始。", figures: ["盛宣怀","李鸿章"], place: "江苏上海（今上海）", state: "清", sources: ["中国近代史资料丛刊《洋务运动》（轮船招商局卷）","盛宣怀《愚斋存稿》","《申报》论局务诸文"], tags: ["轮船招商局","官督商办"] }, related: ["cn--1883--e01", "cn--1872--e01"] },
  { id: "cn--1885--e02", track: "cn", year: 1885, yearApprox: false, dim: "economy", weight: 2, title: "洋药税厘并订约", summary: "入口税与内地厘金并征，由海关查验。", detail: { background: "《烟台条约》既立，洋药税厘如何并征累年未定；印度鸦片进口之数岁耗华银，清廷以加征为裕计，英国以免厘为市恩。", process: "1885年7月（光绪十一年六月）中英在北京签订管理洋药贸易之续约，定洋药入口由海关与地方会商定章，税、厘并征后始准分销内地，征数较旧制有加；至1886年续定章程，始准由总税务司所设新关查验给单。", impact: "此约为1887年《烟台条约续增专条》实施之张本，鸦片之税源自此由地方私设之卡归海关并征，岁入因而有增；而鸦片之入口数额亦因税重而渐缩，华产土药得代兴于川、滇、黔。", figures: ["载湉"], place: "京师、各通商口岸", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（光绪）东华录》","《海关十年报告》近代史所译本"], tags: ["洋药","税厘并征"] }, related: ["cn--1876--p01", "cn--1887--p01"] },
  { id: "cn--1885--i01", track: "cn", year: 1885, yearApprox: false, dim: "institution", weight: 3, title: "设立督办海军衙门", summary: "海军始有中枢，经费另立名目。", detail: { background: "中法一役暴露南北洋各军各自为政、舰艇无统一调度之弊，朝议谓须立中枢以一事权。", process: "1885年10月（光绪十一年九月）清廷设督办海军军务处（通称海军衙门），以醇亲王奕譞总理海军事务，庆郡王奕劻、北洋大臣李鸿章会同办理，将南北洋各舰、福州船政与旅顺、威海之工悉归调度，并定海军岁费之额。", impact: "海军自此有统一机关，而衙门之款与园工之费相为挪移，议论自此不休；1888年成军之后添舰、购械渐滞，甲午之败论者每归原于海军衙门体制之因循。", figures: ["奕譞","李鸿章","奕劻"], place: "京师、天津", state: "清", sources: ["《清史稿·奕譞传》","中国近代史资料丛刊《洋务运动》（海军卷）","《（光绪）东华录》"], tags: ["海军衙门","北洋","军制"] }, related: ["cn--1875--p02", "cn--1888--i01"] },
  { id: "cn--1885--i02", track: "cn", year: 1885, yearApprox: false, dim: "institution", weight: 3, title: "下诏台湾建省", summary: "闽台分治，刘铭传为首任巡抚。", detail: { background: "法军攻基隆、淡水经年，守吏以福建督抚遥制、呼应不灵为病，台地之宜自立省屡入章奏。", process: "1885年10月（光绪十一年九月）清廷下诏台湾正式建省，改福建巡抚为台湾巡抚，福建事宜归闽浙总督兼理；以刘铭传为首任巡抚，刘氏于年底至台，任内清赋、办防、兴筑铁路、设电报与煤油局。", impact: "台湾自此列于行省，建置之制与内地渐齐，1887年之设县、1889年之清丈即其成效；1895年割台之役所以能支撑数月者，亦以此十年间之经画为基。", figures: ["刘铭传","载湉","慈禧太后"], place: "福建台湾（今台湾）", state: "清", sources: ["《清史稿·刘铭传传》","刘铭传《刘壮肃公奏议》","《（光绪）东华录》"], tags: ["台湾建省","行省制度"] }, related: ["cn--1884--m01", "cn--1885--m02"] },
  { id: "cn--1886--p01", track: "cn", year: 1886, yearApprox: false, dim: "politics", weight: 3, title: "中英订立缅甸条款", summary: "英并缅甸，约订十年一贡之文。", detail: { background: "1885年秋英军尽占缅甸，清廷以属邦之谊与英使往复争执，驻英公使曾纪泽力争尤力，朝意终主速结。", process: "1886年7月24日（光绪十二年六月二十三日）总理衙门与英国公使在北京订《缅甸条款》三款，约明中国默许英国处置缅甸之事，英国允听缅甸每十年选派人员循旧例呈递方物；条款并及中缅边界通商事务。", impact: "缅甸之宗藩名义仅存一「呈递方物」之文，其实权已归于英；此约为清廷失去第一个西南大属邦之据，1894年《续议滇缅界务条款》更划定边界，论清代属邦体制之终者常并举二约。", figures: ["曾纪泽","奕訢"], place: "京师", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》（王亮编）","《（光绪）东华录》"], tags: ["缅甸","宗藩","中英"] }, related: ["cn--1885--p01", "cn--1886--m01"] },
  { id: "cn--1886--m01", track: "cn", year: 1886, yearApprox: false, dim: "military", weight: 2, title: "北洋舰队访日与长崎事件", summary: "水兵登岸与日警相哄，交涉经年。", detail: { background: "北洋海军自1881年代渐成，定远、镇远两铁甲既至，1886年夏遣往日本长崎下坞修船，并观览其船坞工事。", process: "1886年8月间，水兵两轮登岸与日本警察冲突，互相杀伤，双方死伤之数各据册报、多寡不一；日方要求照会查办，李鸿章以中国兵轮方抵东瀛、不宜示弱相折，交涉延至1887年始结，日方给恤银而两造所记数目有异。", impact: "此为成军后北洋舰队第一次外事风波，日本舆论借之倡扩充海军之议，清廷则视为巡海之便；两国之比较自此入于互相窥测之局，论甲午前十年之日清军备竞赛者每以长崎为起点。", figures: ["丁汝昌","李鸿章"], place: "日本长崎", state: "清", sources: ["《（光绪）东华录》","《清史稿·丁汝昌传》","中国近代史资料丛刊《中日战争》"], tags: ["长崎事件","北洋海军","交涉"] }, related: ["cn--1888--i01", "cn--1886--p01"] },
  { id: "cn--1887--p01", track: "cn", year: 1887, yearApprox: false, dim: "politics", weight: 3, title: "中葡订约许管澳门", summary: "约文许葡永驻管理澳门及属澳之地。", detail: { background: "葡萄牙自1840年代后渐停向华输纳地租，并欲令华民货税归其征收；总税务司赫德为中间奔走，清廷以换约通商为换取，且欲借约文防他国占澳。", process: "1887年3月26日（光绪十三年三月初二日）总理衙门与葡萄牙使臣在北京订《中葡和好通商条约》并专条，约明中国允许葡萄牙国永驻管理澳门以及属澳之地，又约明未经中国首准，葡国不得将澳门转让他国。", impact: "澳门之治理自此见于约文，而「不得让与他国」一款又为日后中葡、中英相互牵制之据；1928年中外改订新约时，该约期满之议再起，澳门地位遂成近代悬案之一。", figures: ["赫德","奕訢"], place: "京师、广东澳门", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《（光绪）东华录》","《中葡和好通商条约》原约文本"], tags: ["澳门","中葡条约","租借"] }, related: ["cn--1887--e01", "cn--1898--p03"] },
  { id: "cn--1887--e01", track: "cn", year: 1887, yearApprox: false, dim: "economy", weight: 2, title: "台湾铁路兴工", summary: "台北至基隆一段先成，商办改归官。", detail: { background: "台湾建省以后，刘铭传以山地运道艰阻、煤茶不能出港，奏请兴造铁路，议先由商务绅商承办。", process: "1887年（光绪十三年）台北至基隆、台北至新竹两路同时测量兴工，绅商认股不就，旋改归官办，以商款与官项合支；基隆至台北一段于1891年通车，台北至新竹段1893年成，费用数倍于原估。", impact: "此为中国自筑铁路较早之一段，亦台湾近代交通之始；因款绌而中途辍议，南路未成，1895年日军由北路进犯时铁路反为其转运之用，论台省建设之速与未竟者同及此路。", figures: ["刘铭传","邵友濂"], place: "台湾台北至基隆、新竹", state: "清", sources: ["《清史稿·刘铭传传》","连横《台湾通史》","《（光绪）东华录》"], tags: ["台湾铁路","交通","建省"] }, related: ["cn--1885--i02", "cn--1909--s01"] },
  { id: "cn--1888--i01", track: "cn", year: 1888, yearApprox: false, dim: "institution", weight: 3, title: "北洋海军成军定章", summary: "水师章程颁行，提督镇协有等。", detail: { background: "自1875年定策海防，历购定远、镇远诸舰，至光绪十四年间舰艇渐多，非有营制饷章不能统一。", process: "1888年（光绪十四年）秋北洋海军正式成军，以丁汝昌为提督，定提、镇、营、哨之制，订《北洋海军章程》颁行，舰艇凡数十艘（说者多寡不一），以威海卫、旅顺为坞岸基地，岁饷由海军衙门核拨。", impact: "成军定章使北洋海军一度为亚洲之冠，然章程既立则编制遂定，此后外国舰械之购屡以经费为阻，各国海军造舰之法日新；1894年黄海一役，舰速、弹药与编制之病俱见。", figures: ["丁汝昌","奕譞","李鸿章"], place: "山东威海卫、奉天旅顺", state: "清", sources: ["《北洋海军章程》光绪刊本","《清史稿·丁汝昌传》","中国近代史资料丛刊《中日战争》"], tags: ["北洋海军","军制","成军"] }, related: ["cn--1885--i01", "cn--1895--m01"] },
  { id: "cn--1889--p01", track: "cn", year: 1889, yearApprox: false, dim: "politics", weight: 3, title: "光绪帝大婚亲政", summary: "帝行大婚而亲政，西郊训政仍分权。", detail: { background: "载湉入承大统时年仅四岁，两宫垂帘历十余年，至光绪十五年已届大婚之期，归政之仪遂不可缓。", process: "1889年正月（光绪十五年）光绪帝行大婚礼，孝定景皇后立；二月行亲政礼，慈禧太后还宫，仍留训练之权，要枢各臣之进退、颐和园工程之经费多关后意；翁同龢以师傅得进用。", impact: "亲政之后两宫各有所用之人，帝党、后党之名由此而起，1894年之战争方略与1898年之变法皆在此二元权力之下展开；论戊戌政变之根者常原于此年之「归政而未尽还」。", figures: ["载湉","慈禧太后","翁同龢"], place: "京师、颐和园", state: "清", sources: ["《清史稿·德宗本纪》","《翁同龢日记》","《（光绪）东华录》"], tags: ["亲政","两宫","光绪"] }, related: ["cn--1874--p01", "cn--1898--p02"] },
  { id: "cn--1889--e01", track: "cn", year: 1889, yearApprox: false, dim: "economy", weight: 3, title: "改筹卢汉干路与鄂省设厂", summary: "张之洞调湖广，移铁厂于汉阳。", detail: { background: "1888年筹议铁路，原议先修卢汉；张之洞由两广总督调任湖广，乃以钢铁与铁路相须为用，改筹设厂自造路轨。", process: "1889年（光绪十五年）张之洞到任，奏请以卢沟桥至汉口为干线，同时于大冶采铁、汉阳设炼铁之厂，向英国订购炉机；1890年冬汉阳铁厂兴工，铁路之款则另筹商借。", impact: "湖北由是成近代钢铁工业之重心，汉阳铁厂与后来的汉冶萍公司皆基于此；而厂、路经费相掣，借款须取外债，芦汉路款之议遂开比、法债款与路权交涉之门。", figures: ["张之洞"], place: "湖北汉阳、大冶", state: "清", sources: ["《张文襄公全集》","中国近代史资料丛刊《洋务运动》（汉阳铁厂）","《（光绪）东华录》"], tags: ["汉阳铁厂","卢汉铁路","官办工业"] }, related: ["cn--1880--e02", "cn--1890--e01"] },
  { id: "cn--1890--e01", track: "cn", year: 1890, yearApprox: false, dim: "economy", weight: 3, title: "汉阳铁厂兴工", summary: "大冶之铁、焦山之煤，就汉口炼之。", detail: { background: "芦汉干路需轨料，议者谓购于外洋不如自炼；张之洞以铁厂与铁路为表里，先定厂基而后购机。", process: "1890年冬（光绪十六年）汉阳铁厂在龟山脚下兴工，兼采大冶之铁矿，炼焦之炉设于武昌近县，所聘外国矿师以地质未详而焦料不继，炉桥之制屡更，厂至1893年粗成、1894年始出铁，所费较原估增至数倍。", impact: "此为华境第一座兼采冶、炼铁、制钢之近代铁厂，1896年改归盛宣怀商办，1908年合铁厂、矿山与煤矿为汉冶萍公司；中国近代机器冶铁之成本、煤焦与借款诸病，皆可于该厂始末见之。", figures: ["张之洞"], place: "湖北汉阳、大冶", state: "清", sources: ["中国近代史资料丛刊《洋务运动》（汉阳铁厂）","《张文襄公全集》","《（光绪）东华录》"], tags: ["汉阳铁厂","冶铁","汉冶萍"] }, related: ["cn--1889--e01", "cn--1908--e01"] },
  { id: "cn--1891--e01", track: "cn", year: 1891, yearApprox: false, dim: "economy", weight: 2, title: "重庆海关开关", summary: "川江开埠，土产得直输外洋。", detail: { background: "中英前此所订条约许开重庆为通商口岸，川省绅商与地方官以川江滩险、轮舶未通为疑，商务章程累年乃定。", process: "1891年3月（光绪十七年正月）重庆海关开关征税，英商率先入川设行，川省之桐油、猪鬃、药材、白蜡由峡而出，洋纱、洋油则逆流而上；至1896年日本亦设领事，1898年后轮船试行驶川。", impact: "四川之市场自此卷入外洋贸易之网，成都、重庆之手工业与土产价格为其所动；而川江航运之权与税则之争执，遂为1890年代至1900年代教案、路权诸案之背景。", figures: ["刘秉璋"], place: "四川重庆（今重庆）", state: "清", sources: ["《海关十年报告》近代史所译本","王铁崖编《中外旧约章汇编》第一册","《（光绪）东华录》"], tags: ["重庆开埠","川江","海关"] }, related: ["cn--1876--p01", "cn--1895--p01"] },
  { id: "cn--1893--f01", track: "cn", year: 1893, yearApprox: false, dim: "figure", weight: 1, title: "毛泽东生于湘潭韶山", summary: "中南农村一农家子生焉。", detail: { background: "韶山冲属湖南湘潭，其地自太平军以来为游勇、佃农杂处之区，毛氏以耕作并贩米为业。", process: "1893年12月26日（光绪十九年十一月十九日）毛泽东生于湘潭县韶山冲，母文氏，少时入私塾，1910年前后出乡就学于湘乡，1918年入北京大学图书馆工作。", impact: "其生平与1921年后中共革命及1949年后中国政治相终始，本编年于1949年后诸条目所叙人物即此；此处仅作生年之节点，不预论其功过。", figures: ["毛泽东"], place: "湖南湘潭韶山冲", state: "清", sources: ["《毛泽东年谱（1893—1949）》","《韶山毛氏四房支谱》"], tags: ["人物生平","湘潭"] }, related: [] },
  { id: "cn--1894--p01", track: "cn", year: 1894, yearApprox: false, dim: "politics", weight: 3, title: "东学党起事与朝鲜之变", summary: "韩国内乱，清、日同时派兵入朝。", detail: { background: "朝鲜自1882年、1884年两变之后，民教相仇、赋役烦苛，全罗道东学道徒聚众抗官；1885年《天津会议专条》许两国派兵互相关照。", process: "1894年春全琫准等起于古阜，4月陷全州，朝鲜政府请于清；清廷派叶志超等营驻牙山，日本同时依约派大岛义昌混成旅团北进。5月乱议旋定、乱民散，日军仍不退，7月下旬入汉城袭王宫，组织金弘集内阁，继有「甲午更法」之改。（具体日期各史所载朔闰互异）", impact: "朝鲜自此脱离清之宗藩而实际上入于日本影响之下，1895年《马关条约》首载朝鲜「完全无缺之独立自主」；清军之入朝本为镇静，反成开战之由，中日十年之备遂决于一役。", figures: ["全琫准","袁世凯","金弘集"], place: "朝鲜全州、汉城、牙山", state: "清、朝鲜", sources: ["郭廷以编《清季中日韩关系史料》","《（光绪）东华录》","《剑桥中国晚清史》"], tags: ["甲午战争","朝鲜","东学党"] }, related: ["cn--1882--m01", "cn--1894--m01"] },
  { id: "cn--1894--m01", track: "cn", year: 1894, yearApprox: false, dim: "military", weight: 3, title: "成欢之役与丰岛海战", summary: "陆战败于牙山，高升轮沉于海上。", detail: { background: "清军入朝鲜后驻牙山、成欢，日军自汉城南下，两军尚未宣战而前锋已接。", process: "1894年7月25日晨，日军袭成欢、双树里，聂士成军力战而却，叶志超退北走；同日日本巡洋舰浪速在丰岛海面击中国租雇之英国商轮高升号（载清军东渡增援），轮沉，溺亡者众，并击伤济远、掳走操江。8月1日清廷与日本正式宣战。", impact: "不宣而战与击沉租轮两事引起英国对日交涉，日军得志于朝鲜；清军自牙山之退使平壤孤立，黄海之役遂成救护之路；高升轮之案亦成近代海战法与商船地位之要例。", figures: ["聂士成","叶志超","大岛义昌"], place: "朝鲜成欢、丰岛海面（今韩国群山以东海面）", state: "清、日本", sources: ["《清史稿·聂士成传》","中国近代史资料丛刊《中日战争》","《（光绪）东华录》"], tags: ["甲午战争","丰岛","高升轮"] }, related: ["cn--1894--p01", "cn--1894--m02"] },
  { id: "cn--1894--m02", track: "cn", year: 1894, yearApprox: false, dim: "military", weight: 3, title: "平壤弃守", summary: "左宝贵战殁牡丹台，叶志超夜遁。", detail: { background: "牙山既败，清军汇叶志超、左宝贵、卫汝贵诸军共守平壤，筑垒储粮，与军机处电报往复，主守主战之议不一。", process: "1894年9月15日日军分四路攻城，左宝贵守城北牡丹台力战而殁；是夜叶志超悬白旗弃城北遁，一夜走五百里至安州，平壤、价洞军资尽委于敌，清军在朝鲜之根据地全失。", impact: "平壤不战而失，战争遂移于中国境内蒙古、辽东与海面；清廷震动，逮治诸将，议者以是役为甲午败局确定之点，其后旅顺、威海之守皆未能挽回。", figures: ["左宝贵","叶志超","卫汝贵"], place: "朝鲜平壤", state: "清、日本", sources: ["姚锡光《东方兵事纪略》","《清史稿·左宝贵传》","中国近代史资料丛刊《中日战争》"], tags: ["甲午战争","平壤","弃守"] }, related: ["cn--1894--m01", "cn--1894--m03"] },
  { id: "cn--1894--m03", track: "cn", year: 1894, yearApprox: false, dim: "military", weight: 4, title: "黄海大东沟之役", summary: "护航遇敌，海战逾时而北洋退守。", detail: { background: "平壤既失，清廷遣北洋舰队护送陆军援兵至大东沟登陆，归途遇日本联合舰队截击。", process: "1894年9月17日，丁汝昌率定远、镇远等舰至大东沟外海与伊东祐亨所部相遇，自午至申相击数小时；清方致远、经远、超勇、扬威、广甲五舰先后失损，邓世昌以下多殁，日舰松岛、赤城、西京丸等受重创而未沉。是夜北洋舰队回旅顺，不复出海。", impact: "两造互称得胜，而黄海制海权实归于日，此后日军得由海运在辽东、山东两处登陆；论北洋之败者多指弹药、舰速与速射炮之不如，及提督受伤后指挥不续，此役遂为甲午战局转折之点。", figures: ["丁汝昌","邓世昌","伊东祐亨"], place: "奉天东沟外大东洋海面（今辽宁黄海北部）", state: "清、日本", sources: ["中国近代史资料丛刊《中日战争》","《清史稿·丁汝昌传》","日本参谋本部编《日清战争实记》"], tags: ["甲午战争","黄海海战","制海权"] }, related: ["cn--1888--i01", "cn--1895--m01"] },
  { id: "cn--1894--m04", track: "cn", year: 1894, yearApprox: false, dim: "military", weight: 4, title: "旅顺陷与城中杀戮", summary: "台垒一日而溃，入城后数日屠戮。", detail: { background: "旅顺为北洋坞岸，炮台二十余座，而守将诸军分统不相摄，台北诸台先落于陆路之手。", process: "1894年11月21日日军由金州北来，一日之内攻占陆路诸炮台，遂入旅顺，守将败退；入城之后日军连日杀非战斗人员，中外记者与随员各有记载。美国《世界报》记者克利尔曼之通信谓城中尸骸枕藉，仅留数十人从事掩埋，英、美各报转载之，日外部以查无实据为解。", impact: "旅顺一役使北洋失其坞，而城中杀戮成为日后中日与国际舆论之争案，1896年日方准欧美公使入城查勘，两造所记死事人数悬绝、终无定说；论近代战时军民之守护者每引此案。", figures: ["丁汝昌","大山岩","克利尔曼"], place: "奉天旅顺（今辽宁大连旅顺口）", state: "清、日本", sources: ["美国《世界报》1894年12月克利尔曼旅顺通信","中国近代史资料丛刊《中日战争》","《（光绪）东华录》"], tags: ["甲午战争","旅顺","战时杀戮"] }, related: ["cn--1894--m03", "cn--1895--m01"] },
  { id: "cn--1894--p02", track: "cn", year: 1894, yearApprox: false, dim: "politics", weight: 3, title: "兴中会成立于檀香山", summary: "孙中山结华侨为会，首倡共和国。", detail: { background: "孙中山自1892年在澳门、广州行医，与郑士良、陆皓东等往来，以甲午之役清军屡败为可乘之机，赴南洋劝募。", process: "1894年11月24日（光绪二十年十月二十七日）孙中山在檀香山组织兴中会，会约以「驱除鞑虏，恢复中国，创立合众政府」为指归，入会者多华侨商人，孙眉、邓荫南等助其募款；1895年2月设机关部于香港，10月广州之役未发而败。", impact: "此为以共和为标的之第一个政团，其会所由海外华侨而始，经费亦仰华侨，甲午败后之人心一变，故会得以立；1905年同盟会即合兴中会、华兴会、光复会而成，论革命党派之起源者以此会为始点。", figures: ["孙中山","孙眉","邓荫南"], place: "檀香山（今美国夏威夷）", state: "清、美国属地", sources: ["《孙中山全集》第一卷","《革命文献》（中国国民党中央委员会党史史料编纂委员会编）","《（光绪）东华录》"], tags: ["兴中会","革命党派","华侨"] }, related: ["cn--1894--m02", "cn--1905--p01"] },
  { id: "cn--1895--m01", track: "cn", year: 1895, yearApprox: false, dim: "military", weight: 4, title: "威海卫之役与北洋之亡", summary: "水陆夹攻，刘公岛援绝而降。", detail: { background: "黄海既败，北洋舰队退守威海卫，日议以陆军由山东登陆、水陆合攻以尽歼之。", process: "1895年1月20日前后日军在荣成湾登陆，南取成山角、西攻猇子山炮台，数日内威海陆路炮台尽失，日舰与岸炮合击港内；2月来远、威远夜被鱼雷艇袭沉，定远搁浅自爆，日陆军移炮轰击刘公岛。丁汝昌拒降，于月中旬服毒死，降书以提督印文发出，日舰取刘公岛现存诸舰。", impact: "北洋海军自建制以来十余年之经营，一役而尽，天津、京师之震恐随之，清廷遂决意求和；论晚清海防之成败者，于此见船、炮、台、军之不可分，亦见饷源与体制之病。", figures: ["丁汝昌","伊东祐亨","戴宗骞"], place: "山东威海卫、刘公岛", state: "清、日本", sources: ["中国近代史资料丛刊《中日战争》","《清史稿·丁汝昌传》","《（光绪）东华录》"], tags: ["甲午战争","威海卫","北洋海军"] }, related: ["cn--1894--m03", "cn--1895--p01"] },
  { id: "cn--1895--p01", track: "cn", year: 1895, yearApprox: false, dim: "politics", weight: 5, title: "中日订立马关条约", summary: "割台澎、偿二万万两，许日人设厂。", detail: { background: "威海卫既陷，京师大震，清廷派李鸿章为全权大臣赴日请和；3月李氏在马关遇刺受创，日方以此为加约之口实。", process: "1895年4月17日（光绪二十一年三月二十三日）李鸿章、李经方与伊藤博文、陆奥宗光在马关春濠楼签《马关条约》十一款：中国认朝鲜为完全自主之国，割辽东半岛、台湾全岛及附属岛屿、澎湖列岛与日本，赔军费库平银二万万两，开放沙市、重庆、苏州、杭州为埠，并许日本人在通商口岸任便从事工艺制造、运料免税。", impact: "赔款、割地、设厂三端各为一世之变：偿款须举外债，财政遂与关税、盐厘相缚；割台启五十年之局；许外人在华设厂，则此后之工厂、铁路与矿务皆在条约权利之下竞争。论近代中国之转折，1895年之为界说者最众。", figures: ["李鸿章","伊藤博文","陆奥宗光","载湉"], place: "日本马关（今下关）", state: "清、日本", sources: ["王铁崖编《中外旧约章汇编》第一册","陆奥宗光《蹇蹇录》","《清季外交史料》（王亮编）"], tags: ["马关条约","割台","赔款"] }, related: ["cn--1895--p04", "cn--1895--p02"] },
  { id: "cn--1895--p04", track: "cn", year: 1895, yearApprox: false, dim: "politics", weight: 4, title: "三国干涉还辽", summary: "俄法德勒日还辽，中国益以钜金。", detail: { background: "约文初定，俄国以南满出海口碍其东方政策，先与法、德相商；三国于约成后数日同时照会日本，劝弃辽东。", process: "1895年4月23日（约成后六日）俄、法、德三国照会日本，谓持久占据辽东于日本亦无利；日本以海陆军疲、英援不足，5月5日声明愿受劝告，惟索偿款；11月8日在北京订立《辽南条约》，日本还辽东半岛，中国加给库平银三千万两，另赔守备费。", impact: "还辽之役使清廷与士大夫谓「以夷制夷」果可用，而实则以俄为倚；俄国因是得干涉满洲、订密约、筑东省铁路，日俄冲突遂成，1904年之战即此局之果。论东亚国际关系之重组者以1895年为枢。", figures: ["尼古拉二世","维特","陆奥宗光"], place: "京师、东京、圣彼得堡", state: "清、俄国、日本", sources: ["《清季外交史料》（王亮编）","维特伯爵《回忆录》","马士《中华帝国对外关系史》卷二"], tags: ["干涉还辽","以夷制夷","日俄"] }, related: ["cn--1895--p01", "cn--1896--p01"] },
  { id: "cn--1895--p02", track: "cn", year: 1895, yearApprox: false, dim: "politics", weight: 3, title: "公车上书", summary: "会试举人上书，请拒和而变法。", detail: { background: "马关约成之电至京师，时各省举人集于辇下待对试，士人群聚哗然，康有为因倡为连署上书。", process: "1895年5月间康有为、梁启超、麦孟华等草万言书，请拒和约、迁都、练兵、变法，以都察院为递路；因换约已行、都察院以和局已定不受，上书未成，然抄本传刻于江浙，题为《公车上书记》。署名人数自康氏所记千余人以至近人据题名录考订之数，出入颇大。", impact: "此书不成而名大行，各省举人之聚议自此与报馆、学会相联，士之言政始不入廷议亦得动舆论；1895至1898年之学会、报馆、学堂诸举，论者皆原于此年之车上书。", figures: ["康有为","梁启超","麦孟华"], place: "京师", state: "清", sources: ["《公车上书记》光绪乙未石印本","《康有为自编年谱》（《戊戌变法》丛刊第二册）","茅海建《戊戌变法史事考》"], tags: ["公车上书","举人","变法"] }, related: ["cn--1895--p01", "cn--1895--c01"] },
  { id: "cn--1895--p03", track: "cn", year: 1895, yearApprox: false, dim: "politics", weight: 3, title: "台湾民主国之建", summary: "约成未交，台人自立以拒日。", detail: { background: "割台之约电至台北，官绅联名力争，清廷谕唐景崧、刘永福内渡，台湾巡抚与驻军之势遂无所归。", process: "1895年5月25日（光绪二十一年五月初二日）台北官绅倡建「台湾民主国」，推唐景崧为总统、丘逢甲为义勇统领，改用蓝地黄虎旗，电清廷与各国谓「永属中国」而自主拒日；6月初台北兵乱，唐景崧内渡，刘永福继守台南。", impact: "此政权仅存月余、未被任何外国承认，然台民之抗命自此起，乙未一年之战事皆缘此而长；丘逢甲内渡后之诗与日后台人之记忆，均以「民主国」为一节，论台湾近代身份者屡及此事。", figures: ["唐景崧","丘逢甲","刘永福"], place: "台湾台北、台南", state: "清、台湾民主国", sources: ["连横《台湾通史》","《（光绪）东华录》","日本参谋本部编《明治廿七八年日清战史》"], tags: ["台湾民主国","割台","乙未"] }, related: ["cn--1895--p01", "cn--1895--m02"] },
  { id: "cn--1895--m02", track: "cn", year: 1895, yearApprox: false, dim: "military", weight: 2, title: "乙未之役与台民抵抗", summary: "日军由澳底登岸，台北至台南经五月。", detail: { background: "日本以桦山资纪为台湾总督，命近卫师团南来接收；台中之绅吴汤兴、徐骧、姜绍祖等各召义军，前黑旗军将领亦留守。", process: "1895年5月29日日军由三貂角澳底登岸，6月初入台北，继南进，新竹、桃园义军相持；8月八卦山一战吴汤兴殁，台中陷；10月初日军迫台南，刘永福内渡，11月底日军入台南，全岛始设民政。台民死事之数，日方战报与后来研究出入很大。", impact: "此役使台湾入于日本治理之下五十载，而乙未之溃散与义军之抵抗俱入台人之记忆；清政府于此未措一兵，士论因谓弃台之痛甚于割地，1895年后之倡变法、兴学者多援台事为鉴。", figures: ["吴汤兴","徐骧","桦山资纪"], place: "台湾三貂角至台南", state: "日本、清", sources: ["连横《台湾通史》","日本参谋本部编《明治廿七八年日清战史》","《（光绪）东华录》"], tags: ["乙未战争","义军","台湾"] }, related: ["cn--1895--p03", "cn--1897--c01"] },
  { id: "cn--1895--c01", track: "cn", year: 1895, yearApprox: false, dim: "culture", weight: 3, title: "强学会之立与《中外纪闻》", summary: "士夫结会译报，南北两会相继禁。", detail: { background: "公车上书之后，康有为、梁启超以联结朝士、译印西报为开风气之方，京师言变法者渐众。", process: "1895年8、9月间北京立强学会，设书局译西籍，刊《中外纪闻》（原名《万国公报》，因与广学会报同名而改），梁启超、汪大燮主笔，翁同龢、张之洞皆阴为之地；11月上海强学会继立，1896年1月出《强学报》。未几北京会以御史杨崇伊参劾「私结党与」被禁，上海会亦旋辍。", impact: "会禁而报不停，沪上报馆、学会之设自此岁增，《时务报》即承其余绪；朝士之结会虽为忌者所中，然「学会—报馆—学堂」相为表里之格局已成，论戊戌维新之社会基础者以强学会为始。", figures: ["康有为","梁启超","文廷式","杨崇伊"], place: "京师、江苏上海", state: "清", sources: ["中国近代史资料丛刊《戊戌变法》","《中外纪闻》原刊","梁启超《戊戌政变记》"], tags: ["强学会","报馆","维新"] }, related: ["cn--1895--p02", "cn--1896--c01"] },
  { id: "cn--1896--c01", track: "cn", year: 1896, yearApprox: false, dim: "culture", weight: 3, title: "《时务报》创刊于上海", summary: "旬报主变法，梁启超之文笔风行。", detail: { background: "强学会禁后，黄遵宪、汪康年、梁启超等以报馆续其业，筹款、设馆于上海租界，取「因时务而讲变法」之义。", process: "1896年8月9日（光绪二十二年七月初一日）《时务报》发刊，旬日一册，梁启超主笔，连载《变法通议》，倡开民智、改科举、设学校、兴商会；张之洞、黄遵宪等督抚资助，销数至万余份（报馆自载之数，与近人所核略有出入）。1898年政变后奉旨改为官报，梁氏先已离馆。", impact: "此报成维新言论之总汇，士子争读，各省报馆、学会多受其鼓舞，湖南之《湘报》、澳门之《知新报》相与呼应；而汪康年与梁启超之馆产权争，亦开后来报馆与党派、商人资本相纠之例。", figures: ["梁启超","汪康年","黄遵宪"], place: "江苏上海（今上海）", state: "清", sources: ["《时务报》原刊","《汪康年师友书札》","梁启超《戊戌政变记》"], tags: ["时务报","变法通议","维新言论"] }, related: ["cn--1895--c01", "cn--1897--c01"] },
  { id: "cn--1896--p01", track: "cn", year: 1896, yearApprox: false, dim: "politics", weight: 4, title: "中俄订立御敌互相援助约", summary: "李鸿章使俄，密约成而东省铁路起。", detail: { background: "干涉还辽之后，清廷与朝士多主联俄以日制，俄方亦愿东出取不冻之口；1896年俄皇加冕，清以李鸿章为头等专使往贺。", process: "1896年6月3日驻俄公使许景澄与俄方在莫斯科订《御敌互相援助条约》三条，约明中日若有战事，俄以水陆助中国，准俄舰入中国各口岸，并许俄国筑铁路经黑龙江、吉林直达海参崴；同年9月李鸿章与俄方订合办东省铁路公司合同，华俄道胜银行随之而设，入股分红之约另立。", impact: "密约之文未宣布于各国，而东省铁路与银行俱为其实行，俄之势力自此入满洲，1900年之兵、1903年之拒俄运动与1904年之日俄战争皆由此出；论晚清外交之倚俄者以此为转点。", figures: ["李鸿章","许景澄","维特","尼古拉二世"], place: "俄国莫斯科、圣彼得堡", state: "清、俄国", sources: ["王铁崖编《中外旧约章汇编》第一册","维特伯爵《回忆录》","《清季外交史料》（王亮编）"], tags: ["中俄密约","东省铁路","华俄道胜银行"] }, related: ["cn--1895--p04", "cn--1903--p01"] },
  { id: "cn--1896--f01", track: "cn", year: 1896, yearApprox: false, dim: "figure", weight: 2, title: "孙中山伦敦蒙难", summary: "清使馆缚之欲归，英人救出。", detail: { background: "广州之役败后，孙中山赴欧美募款，1896年秋居伦敦，与旧识英国医生康德黎往来。", process: "1896年10月11日孙中山入清驻英公使馆，被拘留于馆中，馆中议将其装船解回上海；康德黎访得其情，告英外部并投报，伦敦舆论大哗，英政府以公使馆不可用强索之力相胁，10月23日馆方释之；孙氏旋以英文记其始末，名曰《伦敦蒙难记》。", impact: "此事使孙中山得欧美报界之注目，革命之论始入外人视野，且证明驻外公使不能行其法外之捕；1897年孙氏留英读书考察，其建国之议多就此时所涉猎而成，论其思想资源者常及伦敦一年。", figures: ["孙中山","康德黎"], place: "英国伦敦", state: "清、英国", sources: ["孙中山《伦敦蒙难记》（1897年英文单行本）","《孙中山全集》第一卷","英国议会1897年关于中国驻伦敦公使馆之文件"], tags: ["孙中山","伦敦蒙难","外交"] }, related: ["cn--1894--p02", "cn--1905--p01"] },
  { id: "cn--1897--p01", track: "cn", year: 1897, yearApprox: false, dim: "politics", weight: 4, title: "德军强占胶州湾", summary: "巨野案起，德兵夜踞胶澳炮台。", detail: { background: "山东西南乡民与天主教堂积案累年，1897年11月1日曹州巨野县张庄教堂二德国传教士为乡民所杀，德使照会索赔，德皇早有远东不冻口之谋。", process: "1897年11月13日夜德国舰队在胶州湾登陆，次日占炮台与青岛村，山东巡抚李秉衡请以兵相拒而不允；12月德使海靖要索租地、开矿、修路诸端，鲁省防军与驻胶德军相持数月。1898年3月6日总理衙门与海靖订《胶澳租借条约》，借期九十九年，并许山东铁路与开矿之权归德商。", impact: "此为1898年租借地浪潮之发端，俄取旅大、英取威海与新界、法取广州湾皆乘其机；德国在山东之势力与铁路之成，又为1914年对德宣战与1919年巴黎和会之争埋其根本。", figures: ["海靖","李秉衡","载湉"], place: "山东胶州湾（今青岛）", state: "清、德国", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》（王亮编）","《（光绪）东华录》"], tags: ["胶州湾","租借地","教案"] }, related: ["cn--1898--p03", "cn--1899--p02"] },
  { id: "cn--1897--c01", track: "cn", year: 1897, yearApprox: false, dim: "culture", weight: 3, title: "商务印书馆创办于上海", summary: "华童合股设印刷之馆，后主教科。", detail: { background: "上海美华书馆之排印工人夏瑞芳、鲍咸恩、鲍咸昌等，以印刷之业可自立，集华资合股设馆，取「商益国、务求实」之义。", process: "1897年2月11日（光绪二十三年正月初十日）商务印书馆成立于上海，初以印刷账单、簿籍与教会书为主；1902年张元济入主编译，延夏曾佑、蒋维乔等编国民学校教科书，又影印古籍、译述西学，馆址三毁于兵事而三复。", impact: "此馆成近代中国最大之出版机构，教科书、字典、丛书与期刊皆出其手，《东方杂志》《小说月报》俱由此出，新学之传播与古籍之保存同赖其力；论近代知识生产与文化产业者以1897年为起点之一。", figures: ["夏瑞芳","张元济"], place: "江苏上海（今上海）", state: "清", sources: ["王云五《商务印书馆与新教育年谱》","《申报》1897年商务印书馆告白","《（光绪）东华录》"], tags: ["商务印书馆","出版","教科书"] }, related: ["cn--1896--c01", "cn--1902--i01"] },
  { id: "cn--1898--p01", track: "cn", year: 1898, yearApprox: false, dim: "politics", weight: 4, title: "明定国是与百日新政", summary: "四月二十三日下诏，新政叠出百日。", detail: { background: "胶州既失、瓜分之说起，康有为三次上书得达帝前，帝以非变法无以自存，翁同龢为之引导。", process: "1898年6月11日（光绪二十四年四月二十三日）下《明定国是诏》，自是至八月，新政之诏数十下：废八股、改试策论，设京师大、中、小学堂，裁绿营、练新军，许官民上书，立农工商总局与铁路、矿务总局，八月召康有为入对，用杨锐、刘光第、林旭、谭嗣同以四品卿衔参预新政。", impact: "百日之间诏旨数变而用人、饷源、兵权皆不在新政府之手，省、府州县之应者多具文；新政之大部分于政变后尽废，仅存京师大学堂与若干商、学之目，论变法之成败者于此见制度变革须有可执行之机关。", figures: ["载湉","康有为","梁启超","翁同龢"], place: "京师、天津、上海", state: "清", sources: ["中国第一历史档案馆编《戊戌变法档案史料》","《德宗景皇帝实录》","中国近代史资料丛刊《戊戌变法》"], tags: ["戊戌变法","百日维新","新政"] }, related: ["cn--1897--p01", "cn--1898--p02"] },
  { id: "cn--1898--p02", track: "cn", year: 1898, yearApprox: false, dim: "politics", weight: 4, title: "戊戌政变", summary: "太后复训政，六君子死于市。", detail: { background: "新政诏旨叠出而兵权、用人之柄仍出于颐和园，后党、帝党之势已不相容；御史杨崇伊请太后即日训政。", process: "1898年9月21日（八月初六日）慈禧太后自颐和园还宫，幽载湉于瀛台，复行训政，尽革新诏；谭嗣同、林旭、杨锐、刘光第、杨深秀、康广仁于八月十三日被杀于菜市口，康有为由英舰得脱，梁启超由日本公使馆走日本，自立军之谋由是起于长江。", impact: "维新之尝试自此终，言改革之士或死或亡命于海外，清廷中枢之自改革之信用大损；1900年之拳乱、1901年之新政与1905年后之预备立宪，皆在此信用已裂之后，论清末政局之转向者以此为分水。", figures: ["慈禧太后","荣禄","谭嗣同","杨崇伊"], place: "京师", state: "清", sources: ["中国第一历史档案馆编《戊戌变法档案史料》","茅海建《戊戌变法史事考》","《德宗景皇帝实录》"], tags: ["戊戌政变","训政","六君子"] }, related: ["cn--1898--p01", "cn--1900--p03"] },
  { id: "cn--1898--p03", track: "cn", year: 1898, yearApprox: false, dim: "politics", weight: 4, title: "租借地与势力范围之划", summary: "旅大、威海、广州湾、九龙相继议租。", detail: { background: "胶州先例既开，各国以「均势」为词竞索军港与利益范围，总理衙门无以拒之。", process: "1898年3月中俄订《旅大租地条约》，借旅顺、大连湾二十五年；6月中英订《展拓香港界址专条》，新界借期九十九年；7月中英《订租威海卫专条》；11月中法订《广州湾租界条约》，借期九十九年。各国并划铁路、开矿之优先范围于其所占省份。", impact: "沿海军港要地自约文而分，中国之海岸与内地省份同入数国范围，北京政府号令为之一缩；势力范围之图为1899年美国门户开放之照会所起，亦为1919年后收回法权诸案与1928年改订新约所要解决之局。", figures: ["载湉","李鸿章","庆亲王奕劻"], place: "旅大、威海卫、广州湾、新界", state: "清", sources: ["王铁崖编《中外旧约章汇编》第一册","《清季外交史料》（王亮编）","《（光绪）东华录》"], tags: ["租借地","势力范围","瓜分"] }, related: ["cn--1897--p01", "cn--1899--p01", "world--1901--p01"] },
  { id: "cn--1898--i01", track: "cn", year: 1898, yearApprox: false, dim: "institution", weight: 4, title: "京师大学堂开学", summary: "堂立于旧都，全国学堂之总。", detail: { background: "议者自1896年起屡请以京师立大学堂为学堂之纲，孙家鼐奉旨管学事，草定章程，以中学、西学分科渐进。", process: "1898年12月31日（光绪二十四年十一月中旬）京师大学堂开学，先设仕学馆、预备科，以经史、政艺、语言、算学为课程，1902年重建后并设译书局，1904年定《奏定大学堂章程》，分八科、设通儒院。", impact: "此为中国以国立大学为学制之顶之始，民国初改为北京大学，此后学制、教科与学术机关多循此线；一学堂而历戊戌之废、庚子之毁与壬寅之复，足见新教育之艰难与不可回。", figures: ["孙家鼐","梁启超","载湉"], place: "京师（今北京）", state: "清", sources: ["中国近代史资料丛刊《戊戌变法》（京师大学堂诸折、章程）","《北京大学史料》第一卷","《德宗景皇帝实录》"], tags: ["京师大学堂","学制","教育"] }, related: ["cn--1898--p01", "cn--1902--i01"] },
  { id: "cn--1898--c01", track: "cn", year: 1898, yearApprox: false, dim: "culture", weight: 4, title: "《天演论》刊行", summary: "物竞天择之说，风行于甲午以后。", detail: { background: "严复自福州船政学堂肄业、留学英国，归任北洋水师学堂教习，以译西书为开启民智之要，译赫黎《进化论与伦理学》。", process: "译稿先载于天津《国闻汇编》（1897年冬），1898年以《天演论》单行本行世，吴汝纶为之序，以「物竞天择，适者生存」与「人相争而天择之」诸义说群经之外之新理，文取汉以前雅词，读者遍于士大夫。", impact: "此书使进化观念成二十世纪初年中国论政、论学之公共语，自维新、革命之家至中学教科书皆援之；其以自然淘汰说人群之语，亦为后来社会达尔文之论与民族自强之说共所从出，影响及于五四前后之思想界。", figures: ["严复","吴汝纶","赫黎"], place: "天津", state: "清", sources: ["《天演论》光绪戊戌刻本及卷首自序","《严复集》","《国闻汇编》原刊"], tags: ["天演论","严复","进化观念"] }, related: ["cn--1897--c01", "cn--1898--p01"] },
  { id: "cn--1898--i02", track: "cn", year: 1898, yearApprox: false, dim: "institution", weight: 3, title: "湖南新政：学堂与南学会", summary: "一省自为变，学堂、学会、报馆并行。", detail: { background: "戊戌之春，巡抚、臬司皆以湘省为变法之试，时务学堂先立于长沙，湘学会与报馆继之。", process: "时务学堂于1897年冬开学，1898年以梁启超为中文教习，蔡锷、林圭、范源濂等入学，课以经史、舆地与算、化诸学；1898年2月南学会开讲于长沙，黄遵宪、谭嗣同、唐才常主之，并出《湘报》，保卫队、工艺厂、银钱局诸举一时并行。", impact: "湖南成一省自为变法之例，其学会、学堂、报馆相维之法为各省所取镜，而守旧之攻亦最烈，苏舆辑《翼教丛编》以驳之；政变后湘省新案多废，而讲学会课之习犹存，1900年汉口自立军之狱，其人物多出湘省。", figures: ["陈宝箴","黄遵宪","梁启超","谭嗣同"], place: "湖南长沙", state: "清", sources: ["《湘报》原刊","苏舆辑《翼教丛编》","中国近代史资料丛刊《戊戌变法》"], tags: ["湖南新政","时务学堂","南学会"] }, related: ["cn--1898--p01", "cn--1900--p03"] },
  { id: "cn--1898--p04", track: "cn", year: 1898, yearApprox: false, dim: "politics", weight: 2, title: "保国会之立", summary: "以保国、保种、保教相号召。", detail: { background: "胶、旅既租，德、俄之逼日急，京师士夫言变法者以结会为时所忌，会名屡商而后定。", process: "1898年春康有为、梁启超、麦孟华等在北京倡立保国会，定《保国会章程》，其文今存，以「保国、保种、保教」相号召，开会演说者三次，王公、京官与各省举人列名会籍者数百人，名册所载与当时传述之数出入较大。", impact: "御史文悌上疏劾之，谓舍保君而言保国，近于朋党结盟，议者遂以会为不可留，会未久即辍；而士人自任国事、立会以兴论之习已成，1903年之拒俄公会、1905年后各省之国会请愿同志会皆袭其名义与作法，言近世政治结社之始者每及保国会。", figures: ["康有为","梁启超","文悌"], place: "京师", state: "清", sources: ["《保国会章程》及会籍题名，见中国近代史资料丛刊《戊戌变法》","苏舆辑《翼教丛编》","《翁同龢日记》"], tags: ["保国会","结社","维新"] }, related: ["cn--1895--c01", "cn--1903--p01"] },
  { id: "cn--1899--p01", track: "cn", year: 1899, yearApprox: false, dim: "politics", weight: 4, title: "美国门户开放之照会", summary: "海约翰告各国，在华一律不得歧视。", detail: { background: "租借地与势力范围既分，各国于其圈内行海关、口岸费用与铁路运费之优先，美国在华商务惧见排于圈外，美、西战事既毕，美廷益谋通商于远东。", process: "1899年9月6日，美国国务卿海约翰先后致照会于英、德、俄、法、日、意诸国，请其在各自势力范围与租借地内，于中国现行海关税则、口岸费用与铁路运费一视同仁，不得歧视他国商货；至11月各国答复渐至，英、德诸国多附条件而许，俄国于旅大另持议，美国未作正式宣告，报馆遂以门户开放名之。", impact: "1900年7月3日海约翰再发照会，益以保全中国领土与行政完整二语，机会均等自此为各国对华文牍之常语；照会询于各国而不及中国，清廷事后仅由驻美公使伍廷芳声明主权不容损碍，得复照而止，此后历次交涉中二语多为各国所引用而少其实，条约上之根据终未成立。", figures: ["海约翰","伍廷芳"], place: "华盛顿、伦敦、北京", state: "美国、清", sources: ["美国国务院《外交与公有文件·中国卷（1899、1900）》所载海约翰照会原文","马士《中华帝国对外关系史》卷三","王亮编《清季外交史料》"], tags: ["门户开放","美国","机会均等"] }, related: ["cn--1898--p01", "cn--1922--p01"] },
  { id: "cn--1899--p02", track: "cn", year: 1899, yearApprox: false, dim: "politics", weight: 3, title: "义和拳起于山东", summary: "平原、恩县之众与教民相仇，巡抚主抚。", detail: { background: "鲁省西南乡民教相案，1897、1898两年因教案株连而地方骚动日甚，练拳之会遍于乡里，谓刀枪不入，入教者每恃教堂以抗官。", process: "1899年春赵三多先在冠县一带以「助清灭洋」为号，与教民相攻；秋后朱红灯与和尚本明等于平原、恩县、禹城之间聚众，与教民战于杠子李庄，又败官军于森罗殿；巡抚毓贤以其变起于民教相仇，主抚不主剿，奏改义和拳为义和团，给以团旗；12月袁世凯署山东巡抚，易以专剿，1900年春朱红灯等被获，死于济南。", impact: "鲁省之团自是北溢于直隶，京畿、漕路诸处皆有坛口，本年之主抚为次年庚子之乱所自始；毓贤后官山西，1900年7月有太原教案之祸，论者以鲁、晋两案相提，谓其用志一也。", figures: ["毓贤","袁世凯","朱红灯","赵三多"], place: "山东平原、恩县、冠县", state: "清", sources: ["故宫博物院编《清末义和团档案史料》","中国近代史资料丛刊《义和团》","路大荒辑《拳会起源及其他》"], tags: ["义和团","山东","民教相仇"] }, related: ["cn--1900--p01", "cn--1897--p01"] },
  { id: "cn--1899--e01", track: "cn", year: 1899, yearApprox: false, dim: "economy", weight: 3, title: "南通大生纱厂开车", summary: "状元办厂，官机与商股合。", detail: { background: "张謇以马关议后之国权外溢，谓救倾危当自工与学始，回籍筹厂，募商股而借用上海机器织布局存沪之官机。", process: "1895年起集股筹办，以绅领商办为格，官机作本而商股任其费，历四年股本终不能足，1899年秋冬间大生纱厂在南通唐家闸开车纺织，以通州、海门所产棉供之，用洋机而雇华工，厂外继设垦牧、纺织、面粉诸业。", impact: "大生为商办棉纺之能以薄本而持久者，民国初年欧战起而洋货不至，纱业之利最厚，亦终以转借抵押之重而见收于银团；张謇之法以实业、学堂与地方自治相维，南通一县遂为一时言自治者所取则。", figures: ["张謇"], place: "江苏南通", state: "清", sources: ["《张謇全集》","《大生系统企业史》，江苏省政协编写组","《（光绪）东华录》"], tags: ["大生纱厂","绅商","棉纺织"] }, related: ["cn--1895--p02", "cn--1914--e01"] },
  { id: "cn--1900--p01", track: "cn", year: 1900, yearApprox: false, dim: "politics", weight: 4, title: "清廷颁宣战上谕", summary: "端王主其谋，与各国同时开衅。", detail: { background: "直隶团众日盛，1900年5月后掠及京畿，各国使臣请剿，电旨交议，主抚、主剿之论相持；载漪、刚毅等以拳术为可用，端郡王载漪之子议立为大阿哥，各国未承认，其谋益急。", process: "6月11日日使馆书记生杉山彬为董福祥部兵所杀，20日德使克林德往总理衙门途中在东单附近被枪死，各国使馆自21日起被围；6月21日以光绪帝名义颁宣战之诏，数累年以来无端之陵侮，谓与其苟且图存，何若大张挞伐、一决雌雄，同时赏团众、谕各省招募。", impact: "以一中枢与各国同时开衅，为中外关系以来未有之局；诏书至东南而诸督不奉，中央号令之一致自此破，许景澄、袁昶、联元以谏阻被杀，其后庚子之赔款、驻兵与刑曹之案皆缘此诏，次年条约遂有停国考绩之款。", figures: ["载漪","刚毅","许景澄","袁昶"], place: "京师", state: "清", sources: ["故宫博物院编《清末义和团档案史料》","中国近代史资料丛刊《义和团》","李希圣《庚子国变记》"], tags: ["义和团","宣战","庚子"] }, related: ["cn--1900--m01", "cn--1900--p02"] },
  { id: "cn--1900--p02", track: "cn", year: 1900, yearApprox: false, dim: "politics", weight: 3, title: "东南互保之约", summary: "诸督与领事约，不奉诏而守租界。", detail: { background: "宣战之诏未至而上海已闻其议，江、鄂诸总督以奉诏则东南俱焚为虑，盛宣怀居中主联各国之约，各督抚电奏往来相商。", process: "1900年6月下旬，上海道袁树勋与各国领事议订《东南保护约款》，许各国任保护租界与外人之财，两江、湖广任保华民之业，又续定《上海租界权限章程》；两江总督刘坤一、湖广总督张之洞主其始，两广总督李鸿章、山东巡抚袁世凯、闽浙总督许应骙相继取同一办法，诏书至江宁，诸臣以「乱命」不奉。", impact: "外臣与外国立约而不奉中枢之诏，为清代所无有，论者以此为清室已不能号令其臣之据；东南财赋之地得免于兵，而朝廷与督抚之关系自是渐移，论者每以辛亥之各省独立循于此例。", figures: ["刘坤一","张之洞","李鸿章","盛宣怀"], place: "江苏上海、江宁、湖北武昌", state: "清", sources: ["《东南保护约款》约文，见王铁崖编《中外旧约章汇编》第一册","盛宣怀《愚斋存稿》","《庚子西狩丛谈》（吴永口述、刘治襄记）"], tags: ["东南互保","督抚","庚子"] }, related: ["cn--1900--p01", "cn--1911--p02"] },
  { id: "cn--1900--m01", track: "cn", year: 1900, yearApprox: false, dim: "military", weight: 4, title: "联军入都与两宫西奔", summary: "天津既陷，两月而都城破，驾幸西安。", detail: { background: "使馆被围与天津租界被攻之后，英、俄、日、美、法、德、意、奥八国合兵自救，先取大沽炮台以通海道，俄、日之兵至最早。", process: "1900年6月17日大沽炮台陷，7月14日天津陷，各国兵续至；8月初联军自天津沿河而西，攻北仓、杨村，清军与团众累却，8月14日晨抵京师，城遂破，次日两宫由都城西门出奔，经宣化、太原，10月底至西安为行在；联军西犯之众，诸家册报自万余至两万余不等，出入较大。", impact: "都城与西郊园林之劫，自8月下旬起，中外记载俱有明文；奕劻、李鸿章奉命议和，12月22日各国提出和约十二款，次年之条约即其文，其定驻兵自山海经天津至京师铁路沿线、平大沽炮台、划使馆界诸条，使首都不为可守之地，论军政者每及之。", figures: ["西摩尔","瓦德西","载湉","奕劻"], place: "大沽、天津、京师、西安", state: "清、八国联军", sources: ["故宫博物院编《清末义和团档案史料》","李希圣《庚子国变记》","马士《中华帝国对外关系史》卷三"], tags: ["八国联军","庚子","北京"] }, related: ["cn--1900--p01", "cn--1901--p01"] },
  { id: "cn--1900--m02", track: "cn", year: 1900, yearApprox: false, dim: "military", weight: 2, title: "廊坊之阻与天津攻守", summary: "进京之师见阻于廊，天津两月乃陷。", detail: { background: "各国以使馆电音断绝，议自天津进京自卫，天津租界之兵不足，乃征海军陆战队合队而行。", process: "1900年6月10日英国提督西摩尔率各国陆战队自天津乘火车赴京，铁路时被拆毁，18日在廊坊为团众所遮，官军亦至，死者数百（各国战报与后来研究出入很大），退杨村，还保天津；同时天津团众与武卫前军攻老龙头火车站与租界，相持月余，7月9日聂士成攻城西南之租界，中炮死于八里台，13、14日联军总攻击，城遂陷。", impact: "廊坊一阻，各国入卫之师为团众所当，主战者遂信拳术可用；而天津既陷，联军得陆路之便，两月而都城不守，聂士成死而武卫前军无纪，直隶之防尽坏。", figures: ["西摩尔","聂士成"], place: "直隶廊坊、杨村、天津", state: "清、各国", sources: ["中国近代史资料丛刊《义和团》","李希圣《庚子国变记》","马士《中华帝国对外关系史》卷三"], tags: ["廊坊","天津之役","武卫前军"] }, related: ["cn--1900--m01", "cn--1900--p01"] },
  { id: "cn--1900--p03", track: "cn", year: 1900, yearApprox: false, dim: "politics", weight: 2, title: "自立军之狱", summary: "唐才常期以自立军起汉口，事泄死。", detail: { background: "政变后康有为、梁启超走海外，孙文以兴中会图两粤与长江，唐才常往来两者之间，以湘省会党为可用，而庚子北方之乱适为机会。", process: "1900年春唐才常、林圭、秦力山等在汉口设自立会，联络哥老会头目，分设自立军各路，约期同时起；7月上海设中国议会，容闳、严复等与议，以保全疆土、不倚外人为名；8月因会中机关与经费为湖北督署所悉而期日未合，唐才常在汉口被围捕就义，同死者数十人（说者多寡不一），大通一路之军亦起而败。", impact: "自立军以保国为名而欲自立其军，为康、梁与孙文一度合流之尝试；其败使湘省士人之向背为之一变，由保皇而转向革命者自此渐多，1903年之拒俄、1905年之同盟会皆取其人物与经验，而租界内捕交之例亦自此益常。", figures: ["唐才常","林圭","秦力山","容闳"], place: "湖北汉口、安徽大通、上海", state: "清", sources: ["《唐才常供词》，见中国近代史资料丛刊《戊戌变法》","冯自由《革命逸史》","《（光绪）东华录》"], tags: ["自立军","庚子","会党"] }, related: ["cn--1898--i02", "cn--1900--p02"] },
  { id: "cn--1901--p01", track: "cn", year: 1901, yearApprox: false, dim: "politics", weight: 5, title: "辛丑条约之定立", summary: "十一国立约十二款，首都自此不可守。", detail: { background: "自1900年12月22日各国提出和约十二款以后，奕劻、李鸿章在京与使臣议者九月，改订之处止于少数款项，其中惩凶、驻兵、赔款三款为各国所不肯让。", process: "1901年9月7日（光绪二十七年七月二十五日）由庆亲王奕劻、全权大臣李鸿章与英、美、俄、法、德、意、日、奥、比、西、荷十一国使臣订约，凡十二款并附件：改总理各国事务衙门为外务部而班列六部之首，平毁大沽炮台，许各国自京师至山海关铁路沿线驻兵，划定使馆界由使馆自行管理，民教相仇之城镇停止文武考试五年，禁止人民入排外之会，赔款之数以别款载之。", impact: "约成而军队不得驻京师附近、首善之区由外人自守、刑曹之案以条约行之，此为条约体制中前所未有的办法，论者谓清廷之自保自此全倚外人之意；赔款与驻兵二端为民国以后历次交涉之所承，废约之议亦由此而起。", figures: ["奕劻","李鸿章","瓦德西"], place: "京师", state: "清、十一国", sources: ["《辛丑各国和约》约文，见王铁崖编《中外旧约章汇编》","故宫博物院编《清末义和团档案史料》","马士《中华帝国对外关系史》卷三"], tags: ["辛丑条约","驻兵","外务部"] }, related: ["cn--1900--m01", "cn--1901--e01"] },
  { id: "cn--1901--p02", track: "cn", year: 1901, yearApprox: false, dim: "politics", weight: 3, title: "庚子罪案之处分", summary: "首祸诸臣以约文定罪，晋、直停试。", detail: { background: "和约第一款以亲贵王公以下诸人为首祸，各国开列名单，必得其所请而后议罪，清廷于1901年2月下诏自责，同时逐条议处分。", process: "1901年4月至5月间定案：端郡王载漪、辅国公载勋革爵、交宗室圈禁，毓贤、英年、赵舒翘正法（赵舒翘赐自尽），董福祥革职并追论其罪，诸臣之子孙永停考试；山西、直隶等处因教案之城镇停文武乡试、会试五年；又遣专使赴德谢克林德被戮之难、赴日谢杉山彬之死，醇亲王载沣于7月抵柏林，那桐赴东京，并在克林德死事之地立碑。", impact: "刑曹之案自外来之名单而出，司法与黜陟之权为条约所制，主战一派自是不振，而后起之督抚以练兵、办学为进阶之路；停试五年一案触动士人之感尤深，论庚子人心之变者每及此。", figures: ["载漪","赵舒翘","载沣","那桐"], place: "京师、太原、柏林、东京", state: "清", sources: ["故宫博物院编《清末义和团档案史料》","《（光绪）东华录》","中国近代史资料丛刊《义和团》"], tags: ["惩凶","庚子","停试"] }, related: ["cn--1901--p01", "cn--1900--p01"] },
  { id: "cn--1901--i01", track: "cn", year: 1901, yearApprox: false, dim: "institution", weight: 4, title: "变法上谕与督办政务处", summary: "西安之诏命条议，政事处主新政。", detail: { background: "銮舆在西安，两宫知非改弦不能自立，和议未成而变法之诏已下，命中外各举所知、各陈所见。", process: "1901年1月底以光绪帝名义下变法上谕，谓世有不易之常经而无一成不变之治法，责成军机处、政务处汇议各奏；4月设督办政务处于京师，以奕劻、李鸿章、荣禄、昆冈、王文韶、鹿传霖督办，刘坤一、张之洞与议；两江、湖广于5月至7月三度会奏，以立学、改兵制、劝工、除候补之积弊为指，其后之废科举、练新军、设商部、订学堂章程多本此数疏。", impact: "庚子以后十年之更张皆以此次上谕为张本，然其行止多系于督抚之请与款之有无，中央之谋与各省之力自是不相离亦不相合；论者谓戊戌之新与辛丑之新名同而势异，戊戌以君命行而诸臣阻之，辛丑诸臣自请行而中枢受成。", figures: ["奕劻","李鸿章","刘坤一","张之洞"], place: "西安、京师、江宁、武昌", state: "清", sources: ["《清末筹备立宪档案史料》，故宫博物院编","《（光绪）东华录》","刘锦藻《清朝续文献通考》"], tags: ["清末新政","督办政务处","江楚会奏"] }, related: ["cn--1905--i01", "cn--1906--p01"] },
  { id: "cn--1901--e01", track: "cn", year: 1901, yearApprox: false, dim: "economy", weight: 4, title: "庚子赔款之额与摊派", summary: "四亿五千万两，分三十九年以关税抵。", detail: { background: "各国以兵费、教案恤款与使馆之毁各开其数，合算之数累次增减，最后以按中国丁口每人一两为定，谓示取偿之有节。", process: "和约第六款定赔款四亿五千万两，分三十九年摊至1940年，年息四厘，本息合计为原额两倍余，以海关税、沿海各口之常关税与各省地丁等项为抵，由各省按额摊派；各国所得之款又以其本国金币之市价折收，故银价之低昂于实数大有关系，1903年上海会议议定以值八先令二便士半之银价折合一镑为补。", impact: "海关与常关之入既为外债之的，财政之权渐分，各省摊款之加派皆出于田赋与货捐，民力自是益困；此项债额历民国而仍偿，1924年后各国始有退还之举，而美国于1908年先以其应得款之半设中国学生游美之费，赔款遂又为办学之资。", figures: ["奕劻","李鸿章"], place: "京师、上海", state: "清", sources: ["《辛丑各国和约》第六款约文，见王铁崖编《中外旧约章汇编》","中国海关《十年报告（1902—1911）》","马士《中华帝国对外关系史》卷三"], tags: ["庚子赔款","关税","摊派"] }, related: ["cn--1901--p01", "cn--1908--i01"] },
  { id: "cn--1901--p03", track: "cn", year: 1901, yearApprox: false, dim: "politics", weight: 2, title: "李鸿章之死", summary: "主约者卒于贤良寺，北洋系无人。", detail: { background: "鸿章自两粤入京议和，身任末议，约既成而病已深，犹以直隶总督兼北洋大臣还任。", process: "1901年11月7日（光绪二十七年九月二十六日）李鸿章卒于京师贤良寺，年七十有九，赠太傅，谥文忠，遗折以就近讲学与练军为请；其直隶总督兼北洋大臣之缺以袁世凯接任，淮军旧部与北洋海防之业自是渐归袁氏之手。", impact: "自是外交与北洋之权合于一人，历次之约多有出于袁世凯之意者；论者谓同光以来以一人当外交之局数十年者，前无与比，其后亦无继之者，中枢之于各省，自庚子以后愈不能驭。", figures: ["李鸿章","袁世凯"], place: "京师、天津", state: "清", sources: ["《（光绪）东华录》","李鸿章《李文忠公全书》奏稿、译署函稿","马士《中华帝国对外关系史》卷三"], tags: ["李鸿章","北洋","庚子"] }, related: ["cn--1901--p01", "cn--1903--i01"] },
  { id: "cn--1902--p01", track: "cn", year: 1902, yearApprox: false, dim: "politics", weight: 4, title: "中俄交收东三省之约", summary: "俄许三期撤兵，期至而不行。", detail: { background: "庚子之冬俄以护路、护教为名，兵分入奉天、吉林、黑龙江，东三省几全入俄手，盛京将军增祺与俄地方官私订之约，清廷不敢批准。", process: "1901年驻俄公使杨儒与俄外部议，拒其别开之款十二项，咯血而卒；1902年4月8日（光绪二十八年三月初一日）由驻俄使署与俄外部订《交收东三省条约》八条，俄承认兵分三期、每六个月而尽撤，撤后中国当自行保护俄人所修之铁路，各国闻之以为约外尚有节目。", impact: "第一期届满而俄不续撤，更于1903年4月提出七条要求，以东三省之兵、官、税诸事归俄任意，1903年拒俄之会由此而起；俄之不肯退遂与日本之冲突，明年日俄之战即在奉天、辽阳之地，而清廷以中立分之，东三省自是为日、俄角立之场。", figures: ["杨儒","增祺"], place: "圣彼得堡、奉天", state: "清、俄国", sources: ["《交收东三省条约》约文（1902年4月8日订），见王铁崖编《中外旧约章汇编》","《（光绪）东华录》","刘锦藻《清朝续文献通考》"], tags: ["东三省","俄国","撤兵"] }, related: ["cn--1903--p01", "cn--1904--p01"] },
  { id: "cn--1902--i01", track: "cn", year: 1902, yearApprox: false, dim: "institution", weight: 3, title: "钦定学堂章程", summary: "壬寅之章先立，各省多未及行。", detail: { background: "变法上谕以立学为急，京师大学堂经庚子之乱停办，1902年冬斋复课，管学大臣张百熙因订通行之章程。", process: "1902年张百熙进《钦定学堂章程》，自蒙养学堂、小学、中学、高等学堂以迄大学堂，又有仕学、师范各章程，计为三级七等，以中学以下归省、府、州、县，大学在京师；章下而各省筹款、改建者寡，行之未能遍。", impact: "壬寅之章为中国以一路学制告天下之始，然未及一年而有重修之议，1904年初颁《奏定学堂章程》，其学级年限与归口多有改易；癸卯之章行而各省之学堂与游学遂不可计，科举之废亦在明年，二者相因为用。", figures: ["张百熙"], place: "京师", state: "清", sources: ["《奏定学堂章程》，张之洞、荣庆等重订，见《清末筹备立宪档案史料》","《（光绪）东华录》","陈学恂主编《中国近代教育史教学参考资料》"], tags: ["壬寅学制","学堂","张百熙"] }, related: ["cn--1904--i01", "cn--1905--i01"] },
  { id: "cn--1902--e01", track: "cn", year: 1902, yearApprox: false, dim: "economy", weight: 3, title: "马凯续约与加税免厘之议", summary: "英约许加税以代厘金，卒不行。", detail: { background: "辛丑约第十二款以改通商章程、行船章程为请，英国于1902年先与议订，其意在于除厘金而换取加税，中国之愿亦在得此一项以整商税。", process: "1902年9月5日《中英续议通商行船条约》订于上海，英使马凯与吕海寰、盛宣怀当议，定将进口税加至值百抽十二两五钱，一税之后不得重征，内地厘金概行停撤，又定内江行船之章、商标注册之章、禁止吗啡与出口土药之税，并许改良矿律与华工出洋之雇规；加税免厘须俾各国一律允从而后行。", impact: "各国以加税之益分而后先不同，遂致1903年上海会议不能有成，厘金之停遂成虚语，一直征至南京政府成立之后；然商标、注册、行船与矿律诸端自此渐有成文，华商之在公司注册者亦以是为据。", figures: ["马凯","吕海寰","盛宣怀"], place: "上海", state: "清、英国", sources: ["《中英续议通商行船条约》约文（1902年9月5日订），见王铁崖编《中外旧约章汇编》","《（光绪）东华录》","中国海关《十年报告（1902—1911）》"], tags: ["商约","厘金","加税免厘"] }, related: ["cn--1901--e01", "cn--1903--i01"] },
  { id: "cn--1902--c01", track: "cn", year: 1902, yearApprox: false, dim: "culture", weight: 2, title: "山西大学堂之开", summary: "教案赔款移作学堂之资。", detail: { background: "庚子山西一案，教士被戕者众，各国索偿甚急，李提摩太以办大学代偿之议进，山西绅僚主其成。", process: "1901年议定以山西各属赔款五十万两设立山西大学堂，1902年开学，分中、西两学专斋，西学专斋由李提摩太主持其事凡十年，筹款设译书局于上海，延教习、定课程，格致、工程、医学诸科并立。", impact: "以一省之赔款为一省之学堂，此为教案处分中之别开一面者，各省效之而不得其人；山西大学堂后为山西大学之前身，而庚子赔款之充学款者，于京师大学堂、于清华学校亦有同一之办法。", figures: ["李提摩太","岑春煊"], place: "山西太原", state: "清", sources: ["李提摩太《留华四十五年记》","《（光绪）东华录》","《山西大学堂章程》，见《清末筹备立宪档案史料》"], tags: ["山西大学堂","教案赔款","新学"] }, related: ["cn--1901--p02", "cn--1902--i01"] },
  { id: "cn--1902--i02", track: "cn", year: 1902, yearApprox: false, dim: "institution", weight: 2, title: "中国教育会与国民学校", summary: "士人自办学社，退学之众附之。", detail: { background: "1902年冬南洋公学以风潮退学者至百数十人（人数各册所载多寡不一），校舍之外无受业之所，海上士夫因议自设学社。", process: "1902年春蔡元培、叶瀚、蒋智由、章炳麟等在上海设中国教育会，以开办学校、编辑书籍、广设分会为事，秋冬间设国民学校，旋又以退学之生徒设爱国学社，寄于务本里，社员自讲《苏报》诸报，演说于张园；1903年苏报案起，会事渐替，蔡元培旋返绍兴讲学，是年冬应商务印书馆编译所之聘。", impact: "以士人自醵款办学、自立学社，为后来教育会与学会之滥觞，张园之演说亦启上海言国事者公开结会之法；爱国学社之生徒多有东渡留学者，1903、1904两年之革命言论多出其人。", figures: ["蔡元培","章炳麟","吴稚晖"], place: "上海", state: "清", sources: ["《蔡元培全集》","中国近代史资料丛刊《辛亥革命》","《苏报》1903年原刊"], tags: ["中国教育会","爱国学社","民间办学"] }, related: ["cn--1903--p02", "cn--1902--c01"] },
  { id: "cn--1903--p01", track: "cn", year: 1903, yearApprox: false, dim: "politics", weight: 4, title: "拒俄运动会", summary: "俄约七条传，学界开会与义勇队。", detail: { background: "1903年4月俄国不撤兵而别提七条之文传于上海、东京，学生与绅士以东三省之存亡为言，而和议诸臣莫能主。", process: "1903年4、5月间上海张园开国民拒俄大会，到者千数百人（报馆所载之数不一），发电责外部；留日学生于东京开大会、组拒俄义勇队，旋改称军国民教育会，派员归国联络，京师大学堂学生亦有上书之举；湖广、两江诸臣电请速战者相属，清廷以会众名为拒俄、实倡革命，命随时查拿，上海《苏报》之论由此益显。", impact: "以学生与城市绅商公然会议外交，为此前所无有，各省之开会遂不可塞；拒俄之会中人多转向排满，1905年同盟会之会员半出于此，而清廷之查拿亦使士人之离心日甚，此后可解之结渐少。", figures: ["蔡元培","黄兴","陈天华"], place: "上海、东京、京师", state: "清", sources: ["中国近代史资料丛刊《辛亥革命》","冯自由《革命逸史》","《（光绪）东华录》"], tags: ["拒俄运动","学生","张园"] }, related: ["cn--1902--p01", "cn--1903--p02"] },
  { id: "cn--1903--p02", track: "cn", year: 1903, yearApprox: false, dim: "politics", weight: 4, title: "苏报案", summary: "以报章罪人，狱成于租界会审。", detail: { background: "《苏报》一报自1903年夏渐言革命，刊《革命军》序与驳康有为论革命之文，两江总督魏光焘屡电外部，请由租界交人。", process: "1903年6月底章炳麟自投于公共租界巡捕房，翌日邹容投案，《苏报》随被封；清廷请以“交华官治罪”，租界以会审公廨鞫之，1904年春会审定章炳麟监禁三年、邹容二年，皆在西牢执役，邹容于1905年死于狱。", impact: "以本国政府就报馆文字之罪诉于租界之法庭，而不得其人之交，此例一开，言者与报馆皆以租界为可恃之地，海上之政论自是益无所忌；二案并传，而《革命军》之销数由是倍增，说者谓狱成而书始行。", figures: ["章炳麟","邹容","陈范"], place: "上海", state: "清、租界", sources: ["《苏报》案卷宗，见中国近代史资料丛刊《辛亥革命》","《章太炎政论选集》","《邹容集》"], tags: ["苏报案","会审公廨","报章"] }, related: ["cn--1903--c01", "cn--1903--p01"] },
  { id: "cn--1903--c01", track: "cn", year: 1903, yearApprox: false, dim: "culture", weight: 3, title: "《革命军》之刊行", summary: "一书出而“革命”二字不可侮。", detail: { background: "辛丑以后留学生东渡者日众，康有为、梁启超之说尚主保教与立宪，少年之士别求一快直之文。", process: "1903年邹容在上海成《革命军》一书，分七章，以“中华共和国”为归，谓中国为中国人之中国，章炳麟为之序，大同书局刊行不署名；书出而两江督署访之甚急，遂有苏报之狱，翻印之本在光、宣之间至十余种（说者多寡不一）。", impact: "此为近代以明白之文字倡共和国体之第一部书，其语径、其旨要皆为后之论革命者所取材，论者谓自是“革命”二字不复为犯上之言；一册之销与各省之重印，亦足见石印时代书籍流传之速。", figures: ["邹容","章炳麟"], place: "上海", state: "清", sources: ["《革命军》原刊本，见张枬、王忍之编《辛亥革命前十年间时论选集》","《邹容集》","《章太炎政论选集》"], tags: ["革命军","邹容","书报刊行"] }, related: ["cn--1903--p02", "cn--1905--p01"] },
  { id: "cn--1903--i01", track: "cn", year: 1903, yearApprox: false, dim: "institution", weight: 2, title: "商部之设与商律之定", summary: "政府始有劝工之专衙门。", detail: { background: "厘金、关卡与候补之积习为商人所苦，历次商约又许以改定律例为言，袁世凯、张之洞因有设立衙门之请。", process: "1903年9月设商部，以宗室载振为尚书，掌劝工、保商、路矿、公司注册之事；1904年初订《钦定大清商律》与《公司注册试办章程》，凡公司之开须呈部注册，次年又定商部审判处与各级商约之章程。", impact: "公司、商标、注册自此有可据之文，沿海之工厂、银行、矿务多以有限公司之名义呈部领取，民间之资本始有一可循之格；然部权所及仅在呈注册者，各省之抽捐与关卡如故，商民之望于官者，遂自是转为求自治与求路权。", figures: ["载振","袁世凯","张之洞"], place: "京师", state: "清", sources: ["《钦定大清商律》，见《清末筹备立宪档案史料》","《（光绪）东华录》","刘锦藻《清朝续文献通考》"], tags: ["商部","商律","公司注册"] }, related: ["cn--1902--e01", "cn--1905--e01"] },
  { id: "cn--1904--p01", track: "cn", year: 1904, yearApprox: false, dim: "politics", weight: 4, title: "日俄战争与局外中立", summary: "两国构兵于我境，朝廷宣布中立。", detail: { background: "俄、日在东三省与韩、半岛之势两不相下，英日同盟成于1902年，俄之不为退兵益显然，谈判于东京、彼得堡皆不合。", process: "1904年2月8日夜日本海军袭旅顺口俄舰，9日绝交，10日两国宣战，陆路战事自朝鲜北进，会于辽阳、奉天，海上相持于旅顺；2月12日清廷宣布局外中立，划辽河以东为战区，其地之供亿、其民之死亡，中外记载皆有明数而多寡不一。", impact: "以中国之地为中国之中立，而战区之供亿皆出于奉天、吉林之民，日、俄战后各据南满、北满之权益，辽东之租借与安奉铁路皆移于日，此民国后二十一条与奉天问题之根；日胜俄败，论者转相引证，谓以小国能胜大国，日人之例于中国变法与立宪之议助益不少。", figures: ["乃木希典","东乡平八郎"], place: "旅顺、辽阳、奉天、东京", state: "清、日本、俄国", sources: ["《日俄战争档案史料》，辽宁省档案馆编","《（光绪）东华录》","马士《中华帝国对外关系史》卷三"], tags: ["日俄战争","中立","东三省"] }, related: ["cn--1902--p01", "cn--1905--e01", "world--1904--m01"] },
  { id: "cn--1904--p02", track: "cn", year: 1904, yearApprox: false, dim: "politics", weight: 3, title: "英军入拉萨与拉萨专约", summary: "兵至佛地而约成，驻藏大臣未与其签。", detail: { background: "自1888年哲孟雄之界案以后，英屡求通藏不得，俄人在藏之谣说适为张本，1903年英以荣赫鹏为入藏议事之员，江孜之会不成，边地越境构兵。", process: "1904年8月3日英军入拉萨，达赖十三世先走外蒙古，驻藏大臣有泰在拉萨而不得与闻其事；9月7日与西藏地方官订《拉萨专约》，定商埠、通信、赔款诸事，赔款之数累经减改，其额各册所载多寡不一；清廷以约非钦差全权所定，不即批准，另派唐绍仪与英重议，1906年北京续订藏印条约，英国允不占并藏境、不干涉藏政，中国则认英在藏通商之办。", impact: "藏案自此由地方之冲转为首都之约与外务之局，拉萨与内地之关系经此益见其形，论者每以1904、1906两约为以后藏防与藏政之枢纽，亦为宣统以后川、藏用兵与1912年后藏局争执之所自始。", figures: ["荣赫鹏","有泰","达赖十三世"], place: "西藏拉萨、江孜、北京", state: "清、英国", sources: ["《拉萨专约》约文，见王铁崖编《中外旧约章汇编》","马士《中华帝国对外关系史》卷三","王亮编《清季外交史料》"], tags: ["西藏","拉萨专约","英案"] }, related: ["cn--1904--p01", "cn--1906--i01"] },
  { id: "cn--1904--p03", track: "cn", year: 1904, yearApprox: false, dim: "politics", weight: 2, title: "光复会之立", summary: "沪上结会，以光复为言，与会党通声气。", detail: { background: "癸卯、甲辰之际，江浙之士以会党与新军为可结之两途，不取同盟会之纲目，自为立会。", process: "1904年冬蔡元培、陶成章、龚宝铨等在上海设光复会，以光复汉族、建立共和为指，推蔡元培任会长，陶成章往来金华、绍兴、台州之间联络平阳党、哥老会诸部，又入新军、巡防营中设分部；1905年冬并入中国同盟会，而江浙之人自为其事，会名不废。", impact: "光复会之人与会党、游民之结合最久且深，其行事以暗杀与新军之起为两途，1907年之皖、浙与1911年之光复上海、杭州皆出此系；论辛亥革命之江浙光复者谓其组织自甲辰始。", figures: ["蔡元培","陶成章","龚宝铨"], place: "上海、绍兴、金华", state: "清", sources: ["陶成章《浙案纪略》","《蔡元培全集》","冯自由《革命逸史》"], tags: ["光复会","会党","暗杀"] }, related: ["cn--1905--p01", "cn--1907--p02"] },
  { id: "cn--1904--i01", track: "cn", year: 1904, yearApprox: false, dim: "institution", weight: 3, title: "奏定学堂章程与末科会试", summary: "癸卯之章既行，甲辰一榜遂止。", detail: { background: "壬寅章程下而各省多未及行，管学之任迭更，湖广、直隶诸臣请以科举与学堂并途之敝痛言之。", process: "1904年1月张之洞、荣庆与张百熙重订《奏定学堂章程》（癸卯学制）颁行，通国一律，自初等小学至大学堂分四段十二级，年限合计二十年，附师范、实业两途；同年7月甲辰科会试、殿试举行，此为最后一次，一甲三名中刘春霖之名遂为末科进士之尾。", impact: "癸卯之章定后，各省之中学、高等学堂与师范传习所以是有可循之格，游学之费与学堂之款皆出于地方，而科举未废则诸生观望，明年遂有立停之请；末科之举为千百年来士途之一断，闻者或以为幸、或以为戚，论近代社会之动者每取此为标志。", figures: ["张之洞","荣庆","张百熙","刘春霖"], place: "京师、顺天贡院", state: "清", sources: ["《奏定学堂章程》，见《清末筹备立宪档案史料》","《（光绪）东华录》","刘锦藻《清朝续文献通考》"], tags: ["癸卯学制","末科会试","学堂"] }, related: ["cn--1902--i01", "cn--1905--i01"] },
  { id: "cn--1904--m01", track: "cn", year: 1904, yearApprox: false, dim: "military", weight: 3, title: "辽阳之役与奉天之危", summary: "两国会战于辽沈，供亿皆出民力。", detail: { background: "日人自朝鲜北进，俄人守辽阳、奉天之线，两军皆以东北为战地，清廷守中立而令地方供支差徭。", process: "1904年秋辽阳之役，两军相持逾一月，俄军退守开原、铁岭，奉天遂见迫；攻城之炮及于村堡，辽阳、奉天、铁岭诸县之民死于兵、饥与流徙者，中外册报之数多寡不一，无可确计；盛京将军与奉天地方官以办差、支应名目征调于民间。", impact: "以战区之供亿累及奉天一省，战后之赈、之抚皆出于地方自筹，日、俄两军之测绘与档案自此备载东北之路、矿、民情；论者谓日俄战争之后果，南满归日、北满归俄，而中国之主权止存于约文之中，东三省之失自此益难收。", figures: ["库罗帕特金","乃木希典","赵尔巽"], place: "奉天辽阳、铁岭、开原", state: "清、日本、俄国", sources: ["《日俄战争档案史料》，辽宁省档案馆编","《（光绪）东华录》","马士《中华帝国对外关系史》卷三"], tags: ["辽阳之役","日俄战争","战区供亿"] }, related: ["cn--1904--p01", "cn--1905--m01", "world--1904--m01"] },
  { id: "cn--1904--e01", track: "cn", year: 1904, yearApprox: false, dim: "economy", weight: 3, title: "川汉铁路公司之设", summary: "一省自办，租股出于田亩。", detail: { background: "芦汉、正太诸路以借款成而权利外分，日俄战后尤以路、矿为交涉之本，川省以地险、路远而议自存其权。", process: "1904年川督锡良奏设川汉铁路公司于成都，官、商合办，寻议定招租股之法，凡田租若干抽若干为路款，商股、土药捐、盐茶加派诸项同为其源，宜昌以上之线自筹自勘，公司之款与股单由地方绅董收发。", impact: "租股之征及于陇亩，路款遂为农民之出，而绅与民皆以路款为我有，论路权者谓川省之办路与东南三省之自赎其路同一情势，1911年之铁路国有一案，川人之争最烈者亦以此；公司所收股款之总数与各年出入，省档与报册所载多有出入。", figures: ["锡良"], place: "四川成都、湖北宜昌", state: "清", sources: ["《（光绪）东华录》","郭廷以《近代中国史纲》","《清朝续文献通考》"], tags: ["川汉铁路","租股","自办"] }, related: ["cn--1905--e01", "cn--1911--p01"] },
  { id: "cn--1904--c01", track: "cn", year: 1904, yearApprox: false, dim: "culture", weight: 2, title: "《东方杂志》创刊", summary: "一杂志兼汇世界之报与学。", detail: { background: "癸卯学制既行，各省之学堂、商报需一汇群言以备览之册，商务印书馆方以编译为业。", process: "1904年商务印书馆在上海创办《东方杂志》，按月一编，取外报之论、各国之政、学界之新说汇而译之，杜亚泉主其笔政最久，并设《科学杂志》《教育报》等诸册相为表里。", impact: "此杂志行年四十余年，于宣统、民国两朝之政论、学衡、科学之介绍所关甚大，言近世期刊之史者以此为商务馆一系之中心；馆之编译所由是聚一国之文士，张元济、高梦旦、蒋百里辈皆出其途。", figures: ["张元济","杜亚泉","高梦旦"], place: "上海", state: "清", sources: ["《东方杂志》原刊（1904—1948）","《商务印书馆九十年》，商务印书馆编","张元济《涉园序跋集录》"], tags: ["东方杂志","期刊","商务印书馆"] }, related: ["cn--1903--i01", "cn--1905--i02"] },
  { id: "cn--1905--i01", track: "cn", year: 1905, yearApprox: false, dim: "institution", weight: 5, title: "停止科举之诏", summary: "一千二百年取士之途一朝而绝。", detail: { background: "自1901年改试策论、1903年议递减中额以来，以科举碍学堂为言者日众，直隶、湖广两督再上急停之请。", process: "1905年9月（光绪三十一年八月）袁世凯、张之洞等会奏请立停科举以广学校，朝廷允其请，谕自丙午科为始，所有乡试、会试与各省岁科试一律停止，其生、贡、举、进士之出路以学堂毕业之格代之；先此两年之会试、殿试已为最后一次。", impact: "士之升进自此舍经义而取学历、留学，四乡之衿监与城市之学堂代易其位，地方之权渐移于新学之绅与军学之人；论者每谓此为秦、汉以来取人之法的最大一断，其所以激于人心、促成辛亥之局者，科举之废与学堂之兴当居其一，而旧士之失所亦为一端。", figures: ["袁世凯","张之洞"], place: "京师、保定、武昌", state: "清", sources: ["《（光绪）东华录》","《张文襄公全集》奏议","《清末筹备立宪档案史料》"], tags: ["废科举","学堂","士绅"] }, related: ["cn--1904--i01", "cn--1905--i02"] },
  { id: "cn--1905--i02", track: "cn", year: 1905, yearApprox: false, dim: "institution", weight: 2, title: "学部之设", summary: "国子监归并，教育始有专部。", detail: { background: "废科举后学堂之设遍于州县，而国子监之任与政务处、学务处之事互相统属，礼、学两权分而无人任其总。", process: "1905年12月（光绪三十一年十一月）设学部，以荣庆为尚书，掌全国之学务、编译、留学与学堂之稽核，国子监随之归并；1906年学部奏定教育宗旨，以忠君、尊孔与尚公、尚武、尚实五事相衡。", impact: "学政之权自此有中央之司，而忠君、尊孔与尚公、尚武之并立，已见新政之两途，其后读经存废之辩皆伏于此；各省之学务公所、劝业公所亦以部章而立，学款之征遂及于庙产与屠、盐之捐。", figures: ["荣庆"], place: "京师", state: "清", sources: ["《（光绪）东华录》","学部奏定教育宗旨折，见《清末筹备立宪档案史料》","刘锦藻《清朝续文献通考》"], tags: ["学部","教育宗旨","新政"] }, related: ["cn--1905--i01", "cn--1906--i02"] },
  { id: "cn--1905--p01", track: "cn", year: 1905, yearApprox: false, dim: "politics", weight: 5, title: "中国同盟会之成立", summary: "三会在东京合组，以共和为纲目。", detail: { background: "甲辰、乙巳之间，留学生东渡者至数千（总数各册所载多寡不一），兴中会、华兴会之党人多在东京，日俄战后人心尤躁，孙文自欧、美至日，合组之议遂定。", process: "1905年8月（七月）兴中会、华兴会、光复会诸人在东京开会，合组中国同盟会，公推孙文为总理，定「驱除鞑虏、恢复中华、创立民国、平均地权」之目，设执行部与各省分部，以《民报》为其机关之报；分会自东京推于南洋、欧洲与长江各埠，会众之总数与题名先后，后来所辑各册互有出入。", impact: "革命之党自此有统一之纲与海外之款，其宣言中「平均地权」一条于当时最启异同，而清廷之立宪遂以党人之活动为反对之据；自1906年之萍浏醴至1911年之武昌，起事者多以同盟会之名义相号召，论民国之肇造者以此会为始点。", figures: ["孙文","黄兴","宋教仁","章炳麟"], place: "日本东京", state: "清、日本侨居地", sources: ["《同盟会宣言》，见中国近代史资料丛刊《辛亥革命》","《民报》原刊","冯自由《革命逸史》"], tags: ["同盟会","孙文","革命党"] }, related: ["cn--1905--c01", "cn--1903--c01"] },
  { id: "cn--1905--p02", track: "cn", year: 1905, yearApprox: false, dim: "politics", weight: 4, title: "五大臣出洋与正阳门之炸", summary: "命近支亲贵周历各国，车站发弹。", detail: { background: "日俄战后，以立宪为可以安内而弭外患者其论渐盛，出洋考察之请起于两湖、直隶诸臣之奏。", process: "1905年7月朝命载泽、戴鸿慈、端方、徐世昌、绍英分赴东西洋各国考察政治；9月24日（八月二十六日）五大臣乘火车出正阳门车站，吴樾怀炸弹起事，炸伤绍英等，吴樾死；改派尚其亨、李盛铎，是年冬启行，载泽等历美、欧、日，1906年先后归国。", impact: "考察之请以兵未成而名已重，明年遂有宣布仿行宪政之诏，而一炸之烈使立宪与革命两途之辨更为士人所留意，吴樾所著《暗杀时代》由是传于少年之会；论预备立宪之始末者每以此为第一事。", figures: ["载泽","端方","戴鸿慈","吴樾"], place: "京师、正阳门车站", state: "清", sources: ["中国近代史资料丛刊《辛亥革命》","《清末筹备立宪档案史料》","《（光绪）东华录》"], tags: ["五大臣出洋","吴樾","考察政治"] }, related: ["cn--1906--p01", "cn--1905--p01"] },
  { id: "cn--1905--p03", track: "cn", year: 1905, yearApprox: false, dim: "politics", weight: 3, title: "抵制美货之议", summary: "沪商会以不用美货为外交之争。", detail: { background: "华工约束之约以1882年以来之禁例为基，期满当改，美廷所拟新约苛待往美之华工，沪、穗之报与商会先持不可。", process: "1905年夏上海商务总会与粤商先施会诸肆开会，以不用美货、不雇美船为约，通电十六省商会与暨南诸埠，限以六月，凡美油、美布、美烟之入口者渐滞；清廷外、商两部以约方修而民自为争，两无所主，至冬其势渐弛。", impact: "以商会为主、以购与不购为手段而争外交之得失，此为前此所无有，其后1908、1915、1919、1925诸次抵货之举皆循此格；报馆与商会由此相结为城市舆论之一途，论近世商人政治之始者多自此年数起。", figures: ["汪康年"], place: "上海、广州、厦门", state: "清", sources: ["《申报》《时报》1905年原载","《（光绪）东华录》","《清朝续文献通考》"], tags: ["抵制美货","商会","华工"] }, related: ["cn--1905--p02", "cn--1905--e01"] },
  { id: "cn--1905--e01", track: "cn", year: 1905, yearApprox: false, dim: "economy", weight: 3, title: "粤汉铁路之自赎", summary: "三省筹银废美约，路权归自办。", detail: { background: "1898年美商合兴公司得办粤汉铁路之借款与修路之权，寻以其股转售比商东方开发公司，三省绅商以路权随股而移为不可，废约之议起于1903、1904两年。", process: "1905年7月由驻美使署与合兴公司订废约之文，三省筹款赔付其股票与本息，赔付之数为银若干，报册、档册与后来所记出入颇大；鄂、湘、粤三省各设公司自办其路，股款取于租、捐与商认，1906年总督端方与三省绅董再定分办之界。", impact: "自赎之例一开，苏杭之路（1905、1906两年赎回）、川汉之自办相率而起，路权遂为绅与商所共有之物，各省之收回路权与抵制借款成为立宪数年中最能鼓动人心之事，铁路国有之诏既下，1911年，川、鄂、湘三省之风潮即缘此而发。", figures: ["梁诚","张之洞"], place: "广东、湖北、湖南、华盛顿", state: "清、美国", sources: ["《粤汉铁路展抵借款废除合同》，见王铁崖编《中外旧约章汇编》","《（光绪）东华录》","王亮编《清季外交史料》"], tags: ["收回路权","粤汉铁路","绅商"] }, related: ["cn--1904--e01", "cn--1911--p01"] },
  { id: "cn--1905--c01", track: "cn", year: 1905, yearApprox: false, dim: "culture", weight: 3, title: "《民报》之刊", summary: "一报揭三义，与《新民丛报》立辩。", detail: { background: "同盟会既立，须一册以宣其纲，与保皇之论相抗，留东学生之能文者多集于此。", process: "1905年冬《民报》月刊创刊于东京，孙文于其发刊词中以民族、民权、民生三者相贯，谓为三义；胡汉民、汪精卫、朱执信、章炳麟先后执笔，自1906年至1907年与梁启超之《新民丛报》反复论难，所争在革命与改良、共和与开明专制、土地与国民生计诸端。", impact: "论难之文遍传于东南之学堂与新军，少年之向于革命者每自报章得之，三民主义之名亦由《民报》而著；其文气之盛、辩说之繁，为近世政论杂志之最，报虽以日、警之禁辍于1910年，翻印与选本在光、宣之间行于各省。", figures: ["孙文","胡汉民","汪精卫","朱执信"], place: "日本东京、上海", state: "清侨居地", sources: ["《民报》发刊词，见《孙中山全集》第一卷","《新民丛报》1906—1907年原刊","中国近代史资料丛刊《辛亥革命》"], tags: ["民报","三民主义","政论"] }, related: ["cn--1905--p01", "cn--1902--i01"] },
  { id: "cn--1905--s01", track: "cn", year: 1905, yearApprox: false, dim: "science", weight: 3, title: "京张铁路勘工之始", summary: "不用外债，自勘自建之路起于居庸。", detail: { background: "关内外铁路之余利既为中国自养之路款，京张一段以地控西北而被俄、英所争，廷议以自办存其权。", process: "1905年冬勘线，詹天佑亲履关沟诸隘，数线比较而后定，由丰台出南口、越居庸关以达张家口，詹天佑任总工程师；其线山岭重叠、坡度陡急，青龙桥一段设折返之线，以两机相推而上，是年冬开工。", impact: "此路以中国之款、中国之工程师自成之，其勘线与记账之文皆由工程处自定，1909年全线告成，论者以是中国路工自立之始；京张之成又启此后自办各路之请，詹天佑之名由是显于当世。", figures: ["詹天佑"], place: "直隶丰台至张家口", state: "清", sources: ["詹天佑《京张铁路工程纪略》","金士宣、徐文述《中国铁路发展史》","《（光绪）东华录》"], tags: ["京张铁路","詹天佑","自办路工"] }, related: ["cn--1909--s01", "cn--1905--e01"] },
  { id: "cn--1905--m01", track: "cn", year: 1905, yearApprox: false, dim: "military", weight: 3, title: "旅顺之陷与奉天之役", summary: "两军决胜于辽沈，和议移南满于日。", detail: { background: "自辽阳之役俄军北退，日人围旅顺、图奉天，两军各以续至之众相抗，奉天一隅为东亚之战场。", process: "1905年1月旅顺俄将出降，日人乃得北犯奉天之便，2、3月间奉天会战，两军相持逾半月，俄军北退，3月10日日军入奉天；5月日本海一役，俄之第二太平洋舰队覆其大半；9月5日朴次茅斯和约成，俄以东三省南边之利让于日；12月中日会议东三省事宜条约成，许日人承其所得之铁路与租借之地，另开商埠十数处。", impact: "战地之供亿、死于兵与流徙之民，中外册报互有详略，无可确计；而约文以东三省南满之铁路、租借归日，1906年南满铁道会社设，日本之驻军与警察权由是入中国之内地，民国以后二十一条与奉天诸案之根皆在此役之后。", figures: ["乃木希典","东乡平八郎","库罗帕特金"], place: "旅顺、奉天、对马海峡、朴次茅斯", state: "清、日本、俄国", sources: ["《中日会议东三省事宜条约》约文，见王铁崖编《中外旧约章汇编》","《日俄战争档案史料》，辽宁省档案馆编","马士《中华帝国对外关系史》卷三"], tags: ["旅顺","奉天会战","南满"] }, related: ["cn--1904--m01", "cn--1906--e01"] },
  { id: "cn--1906--p01", track: "cn", year: 1906, yearApprox: false, dim: "politics", weight: 4, title: "宣布仿行宪政之诏", summary: "以大权归朝廷、庶政归舆论为纲。", detail: { background: "五大臣既出洋，载泽、端方等归国历陈东西各国立宪之利，谓可以保位、安民、去内乱，两宫是之，而亲贵之中异议亦起。", process: "1906年9月1日（光绪三十二年七月十四日）以光绪帝名义下上谕，宣布仿行宪政，以大权统于朝廷、庶政公诸舆论为指，先行更官制、设学堂、练军政、清财政，为立宪之预备，又命载泽、世续、那桐、荣庆、铁良诸臣同任其议。", impact: "自上谕既下，立宪之请自士绅而商会，自报章而集会，一年之内渐成风气，而大权归朝廷一语已定其界，此后谘议局之请愿、国会之速开与十九信条之仓促，皆不外此诏所立之两可之地；论清末立宪之败者多即此二语断之。", figures: ["载泽","端方","世续"], place: "京师", state: "清", sources: ["《宣统政纪》、《（光绪）东华录》","《清末筹备立宪档案史料》","刘锦藻《清朝续文献通考》"], tags: ["预备立宪","仿行宪政","上谕"] }, related: ["cn--1905--p02", "cn--1906--i01"] },
  { id: "cn--1906--p02", track: "cn", year: 1906, yearApprox: false, dim: "politics", weight: 3, title: "萍浏醴之役", summary: "矿工与会党并举于萍乡、浏阳。", detail: { background: "萍乡煤矿、浏永之土客与哥老会诸堂素相结，同盟会之刘道一、蔡绍南归国谋以路矿之人为用，会党之众以食、以捐为怨。", process: "1906年冬（十月）萍乡、浏阳、醴陵一带会党与矿工起事，推龚春台、蔡绍南主之，号其军以光复为目，发布文告以除苛政、均田价为言，响应者至万余人（册报之数多寡不一），湘、鄂、赣、江苏四省调兵合剿，旬日间事定，刘道一被捕，1907年元旦后死于长沙。", impact: "此为同盟会成立后第一次之起事，其败在会众之无器械、无统一之期，而事起于路矿之地，使湘省之学界与会党自此合流；清廷以立宪之诏方下而有此役，言者因请力行自治以塞其端，主兵者则以新军之不可不练为词，新军之费由是日重。", figures: ["刘道一","蔡绍南","龚春台"], place: "江西萍乡、湖南浏阳醴陵", state: "清", sources: ["中国近代史资料丛刊《辛亥革命》","《（光绪）东华录》","冯自由《革命逸史》"], tags: ["萍浏醴","会党","同盟会"] }, related: ["cn--1905--p01", "cn--1907--p02"] },
  { id: "cn--1906--i01", track: "cn", year: 1906, yearApprox: false, dim: "institution", weight: 3, title: "丙午改订官制", summary: "部院更置，兵权归于陆军部。", detail: { background: "仿行宪政之诏以改官制为最先，考政诸臣以责任内阁、分立各部为说，中枢之权与亲贵之任皆在其中。", process: "1906年冬改订中央官制：改兵部为陆军部，合并旧日之练兵处，裁会议政务处，改巡警部为民政部，户部为度支部，刑部为法部，添设邮传部，礼部兼学务之目；地方督抚之权亦议更定，北洋之四镇兵解归陆军部，直隶之政由是新设之部与旧任之督分持。", impact: "部院之名自是略近各国，而责任内阁之说终未实行，1906年之议至1911年之内阁乃成，论者谓其名为立宪之基、实为亲贵集权之渐；兵权归部而将帅之分寄于各省，北洋一系之不肯听部调亦始于此。", figures: ["载泽","袁世凯","铁良"], place: "京师、保定", state: "清", sources: ["《（光绪）东华录》","《清末筹备立宪档案史料》","刘锦藻《清朝续文献通考》"], tags: ["官制改革","陆军部","邮传部"] }, related: ["cn--1906--p01", "cn--1908--i02"] },
  { id: "cn--1906--i02", track: "cn", year: 1906, yearApprox: false, dim: "institution", weight: 2, title: "学部奏定教育宗旨", summary: "以五事悬为国是，学政自此有指。", detail: { background: "废科举后各省学堂骤兴，游学东渡者岁以千计，朝廷以士风之浮动为忧，学部新设，请以宗旨齐其趋。", process: "1906年学部奏定教育宗旨，以忠君、尊孔与尚公、尚武、尚实五事相并，谓学堂之教当以是为准，通行各省，悬于讲堂；其尚公、尚武、尚实三目取法东西学堂之格，忠君、尊孔二目则仍出于中国之旧。", impact: "五目之中两端属旧、三端属新，学堂之课程遂以是为衡，读经一科之存废自是聚讼，1909、1910两年省教育会之议与谘议局之争多缘此；论者谓一国之教育旨以调和新旧而两无所成，而尚武、尚实二目之于军国民教育与实业学堂之助则显然可见。", figures: ["荣庆"], place: "京师", state: "清", sources: ["学部奏定教育宗旨折，见《清末筹备立宪档案史料》","《（光绪）东华录》","舒新城编《近代中国留学史》"], tags: ["教育宗旨","学部","学堂"] }, related: ["cn--1905--i02", "cn--1909--i01"] },
  { id: "cn--1906--e01", track: "cn", year: 1906, yearApprox: false, dim: "economy", weight: 2, title: "各省自办铁路公司之广", summary: "路权归绅商，股款出于租与捐。", detail: { background: "自赎粤汉、收回京汉借款之议既行，日俄战后路、矿尤关交涉，朝廷亦以自办可以息浮言，乃许各省筹款自修。", process: "1906年前后，江苏、浙江、四川、广东、江西、安徽、湖南诸省相继设商办铁路公司，招租股、加捐、认股诸法并用，公司之总理多出绅士与谘议局之议，商部、邮传部颁其章程而稽其款，自办之路以苏浙、川汉、粤汉之段为最着。", impact: "路款既出于民间，则路事亦为民间所得言，绅商以路公司而得会议、而设报馆、而派员出洋，地方之自治与国会之请愿皆以路事为其练习之所；至1911年以铁路干路收归国有为令，则所收者即此绅商之款，风潮一发而不可收，论辛亥革命之机会者每原于此。", figures: ["汤寿潜"], place: "江苏、浙江、四川、广东、湖北", state: "清", sources: ["《（光绪）东华录》","刘锦藻《清朝续文献通考》","金士宣、徐文述《中国铁路发展史》"], tags: ["商办铁路","租股","路权"] }, related: ["cn--1905--e01", "cn--1911--p01"] },
  { id: "cn--1906--a01", track: "cn", year: 1906, yearApprox: false, dim: "art", weight: 2, title: "春柳社之立", summary: "留东学生以新剧相结，话剧之端兆焉。", detail: { background: "留学生东渡者既众，见日本之新派剧与西方之戏剧，以旧剧之不足以新民气为言，乃以剧事相结。", process: "1906年冬曾孝谷、李叔同等在东京结春柳社，以演新剧为事，定其目以去歌唱、重对话与布景，仿日本之演剧而参以西法，社中诸人多兼为政论之文，1907年以后数度公演，观者以留学界与侨商为主。", impact: "春柳社之演剧为后来言中国话剧之始者所必及，其法自东洋转授而来，归国后之新剧社、开明与民新诸班皆承其余，而言者亦以是谓剧之一端与政论、报章同日并兴，为城市之民开一新耳目之地。", figures: ["李叔同","曾孝谷","欧阳予倩"], place: "日本东京", state: "清侨居地", sources: ["徐半梅《话剧创始期回忆录》","欧阳予倩《欧阳予倩文集》","《民报》1907年原刊"], tags: ["春柳社","新剧","话剧"] }, related: ["cn--1907--a01", "cn--1905--c01"] },
  { id: "cn--1907--i01", track: "cn", year: 1907, yearApprox: false, dim: "institution", weight: 3, title: "东三省改设行省", summary: "将军之制既废，三省始与内地同。", detail: { background: "日俄战后东三省之开放与交涉皆成常事，旗、民二元之治与将军、都统之旧制不能应，省制之改议起于端方、徐世昌诸人之奏。", process: "1907年（光绪三十三年）裁盛京、吉林、黑龙江之将军，改设东三省行省，以徐世昌为东三省总督，唐绍仪、朱家宝等分任巡抚，设交涉、财政、劝业诸司，旗地、蒙地之放垦与铁路、商埠之事务并归省办，另设度支与督练公所以理财与兵。", impact: "东北自此与关内同一省制，奉天、吉林、黑龙江之行政与交涉始有总一之机关，而三省之财用仰于外债与铁路之利，日、俄在南、北之势力皆附于省制之上；辛亥以后东北之局与张作霖之起，其行政之格式皆定于此年。", figures: ["徐世昌","唐绍仪"], place: "奉天、吉林、黑龙江", state: "清", sources: ["《（光绪）东华录》","《清末筹备立宪档案史料》","刘锦藻《清朝续文献通考》"], tags: ["东三省","行省","徐世昌"] }, related: ["cn--1905--m01", "cn--1907--i02"] },
  { id: "cn--1907--i02", track: "cn", year: 1907, yearApprox: false, dim: "institution", weight: 3, title: "谘议局与资政院之筹设", summary: "先立议事之所，以渐为议院之基。", detail: { background: "宣布仿行宪政之后，请设议院之奏日多，考政诸臣以民智未开、先练议事之格为解，谓当自各省始。", process: "1907年秋谕先于各省设立谘议局，并以京师资政院为天下倡，命民政部、学部会同纂拟章程；1908年7月《谘议局章程》与《谘议局议员选举章程》成，定议员之额与选、被选之资以学历、财产、地方之数为格，又颁《钦定宪法大纲》与逐年筹备事宜清单。", impact: "谘议局之设本为议事之练习而非议院，然各省之绅与商既得一堂以议地方之事，遂以议学款、议租股、请开国会相号召，1910年三次请愿与1911年之争皆自局而出；论清末立宪之实际运动者，多以谘议局为士绅参预政权之第一阶。", figures: ["载泽","善耆","荣庆"], place: "京师、各省", state: "清", sources: ["《谘议局章程》，见《清末筹备立宪档案史料》","《（光绪）东华录》","张朋园《立宪派与辛亥革命》"], tags: ["谘议局","资政院","章程"] }, related: ["cn--1909--i01", "cn--1908--i02"] },
  { id: "cn--1907--p01", track: "cn", year: 1907, yearApprox: false, dim: "politics", weight: 3, title: "江浙铁路之争", summary: "绅商拒借款，一省以路为公司之公。", detail: { background: "苏杭湖之路先有中英银公司之草约，浙路公司既设，以自办废约相任，而草约未明废也，绅、学、商三途并起。", process: "1907年浙江铁路公司以英款之约碍自办，汤寿潜与省城之绅、学界连电外部争废前约，杭州、绍兴之集会相属于道，上海之商会与报馆内外相应；两江、浙抚以是入告，朝廷以地方勿生事端为诫，且电拿问汤寿潜，浙人益愤，借款草约以是迄不能行。", impact: "以一省之绅商而能阻外部之约，此为收回路权以来最见力量之举，议者自此谓路事可以聚众、报章可以动官；1909、1910两年各省争川汉、粤汉之款与路，其法一循江浙，而朝廷之不能无惧亦以是渐启其收为国有之谋。", figures: ["汤寿潜"], place: "浙江杭州、江苏上海", state: "清", sources: ["《（光绪）东华录》","《时报》《申报》1907年原载","郭廷以《近代中国史纲》"], tags: ["浙路","收回路权","绅商"] }, related: ["cn--1906--e01", "cn--1911--p01"] },
  { id: "cn--1907--p02", track: "cn", year: 1907, yearApprox: false, dim: "politics", weight: 3, title: "安庆之役与轩亭口之狱", summary: "徐锡麟起于巡警学堂，秋瑾死于绍兴。", detail: { background: "光复会之人在皖、浙两省以学堂、新军与会党三线并进，徐锡麟以道员捐班入安庆主巡警学堂，秋瑾在大通学堂主体育会与浙案之约。", process: "1907年7月6日（光绪三十三年五月二十六日）安庆巡警学堂举行毕业式，徐锡麟率陈伯平、马宗汉等以枪击安徽巡抚恩铭，随即攻军械局，事败被执就义；浙省因之大索，秋瑾在绍兴大通学堂被捕，7月15日死于轩亭口，株连者数十人（各册多寡不一），陶成章走海外。", impact: "以学堂之师生为一役之首尾，各省学界闻之震动，秋瑾之死尤使报馆与士论群起，论者谓自是女子之从革命者渐多；而清廷之按狱多及光复会之人名，江浙之党人与会党自此相倚益深，1911年之光复杭州、上海即此辈为之。", figures: ["徐锡麟","秋瑾","恩铭","陈伯平"], place: "安徽安庆、浙江绍兴", state: "清", sources: ["陶成章《浙案纪略》","中国近代史资料丛刊《辛亥革命》","《（光绪）东华录》"], tags: ["徐锡麟","秋瑾","光复会"] }, related: ["cn--1904--p03", "cn--1906--p02"] },
  { id: "cn--1907--a01", track: "cn", year: 1907, yearApprox: false, dim: "art", weight: 2, title: "春柳社演《黑奴吁天录》", summary: "一剧据林纾译本成，观者始知新剧。", detail: { background: "春柳社既立，以有本之剧为演，取林纾译《黑奴吁天录》之意编为脚本，分幕设景，去唱而专用言语、动作。", process: "1907年夏春柳社在东京开会演《黑奴吁天录》，曾孝谷主其事，李叔同、欧阳予倩诸人分任角色，侨商与留学生往观者数百人（报馆所记之数不一），并演《茶花女》遗事诸剧，观者始以话剧为一种独立之剧。", impact: "此剧以美国之黑奴为本事而寄寓意于种族之痛，其上演于侨居之地而回声在东南之报章，上海、杭州之新剧社自是继起；论中国近代戏剧之新格者每以是年为话剧成立之证，而演剧之在留东学社中为风会所趋，亦可见乙巳、丁未间青年之好尚。", figures: ["李叔同","欧阳予倩","曾孝谷"], place: "日本东京", state: "清侨居地", sources: ["徐半梅《话剧创始期回忆录》","林纾译《黑奴吁天录》","《民报》1907年原刊"], tags: ["黑奴吁天录","话剧","新剧"] }, related: ["cn--1906--a01", "cn--1907--p02"] },
  { id: "cn--1907--e01", track: "cn", year: 1907, yearApprox: false, dim: "economy", weight: 2, title: "收回矿权之案", summary: "皖、滇两省以合同为病，赎之以款。", detail: { background: "光绪末年矿务多由地方官与洋商立约，所准之地往往过大，矿股虽未收而山地先失，绅民以路矿并言。", process: "1907年前后，安徽铜官山与云南迤北之矿案同时并起，皖省绅民据原约之地段与年限与英商福公司往复争执，滇省亦以矿约所括之蒙、维诸地过广为言；两案历一二年，至1909年各以偿款赎回而结，赎款之数各册所载出入较大。", impact: "矿权之收与路权之收同为一事，绅、学、商三途因此共立一会一报，其款则摊之于田亩、盐茶与捐输；论清末收回利权之运者以此数年为最盛，而政府之财政因赎约之款与筹办之费愈见其绌，交涉之权与地方之任两不相胜。", figures: ["冯煦","锡良"], place: "安徽铜官山、云南", state: "清", sources: ["《（光绪）东华录》","《清末筹备立宪档案史料》","郭廷以《近代中国史纲》"], tags: ["收回矿权","矿约","绅民"] }, related: ["cn--1907--p01", "cn--1906--e01"] },
  { id: "cn--1908--i01", track: "cn", year: 1908, yearApprox: false, dim: "institution", weight: 3, title: "美国退赔款与游美学务处", summary: "以退款设学，官费游学自此有程。", detail: { background: "自1904、1905两年中国驻美使臣以赔款之数与华工之禁往复辩论，美国廷议谓所得之款过多，宜还其一部分以设中国学生留美之费。", process: "1908年（光绪三十四年）中美就退款之交涉定议，美国以其所得赔款之一部退还，专供派学生游美之用；清廷设游美学务处于京师，附设游美肆业馆，自1909年起先后遣三批学生，并于直隶清华园拓地建校，为民国清华学校之始，退还之款总数各说略有出入。", impact: "赔款之一部分返为教育之资，此在庚子诸债中为创例，英、比、日诸国相继有退款之议；官费游学之格既立，此后留学之费与学历之途相系于政府，而学成归国者多集于工、商、路与大学之用，论近代学术人才之出处者以此为关键之一。", figures: ["梁诚","唐国安"], place: "京师、华盛顿、清华园", state: "清、美国", sources: ["美国国务院《外交与公有文件·中国卷（1907、1908）》","《（光绪）东华录》","《清季外交史料》，王亮编"], tags: ["庚款留学","游美学务处","清华"] }, related: ["cn--1901--e01", "cn--1909--i01"] },
  { id: "cn--1908--p01", track: "cn", year: 1908, yearApprox: false, dim: "politics", weight: 4, title: "两宫崩与溥仪立", summary: "一日而两丧并至，幼帝立而摄政。", detail: { background: "自戊戌以后，训政之局未解，光绪居瀛台，慈禧任大臣之黜陟，戊申之冬两宫俱不豫，御医之请脉日数载于脉案。", process: "1908年11月14日光绪帝崩于中南海涵元殿，年三十有八，次日慈禧太后崩，相距不及两日；是日立溥仪为皇太子、即皇帝位，以载沣为监国摄政王，隆裕皇后垂帘，命以明年为宣统元年；载涛、载洵分掌筹办海军军咨诸事。", impact: "一日两丧而主少国疑，亲贵当国而汉大臣之势渐轻，1909、1910两年之摄政与铁路、军权之归趣，皆成辛亥之局；论者每谓乙巳以后清室之亡在于人之不继，而谘议局之请愿与新军之骚动并起于一二年间，中枢已无任事之人。", figures: ["载湉","慈禧太后","溥仪","载沣"], place: "京师", state: "清", sources: ["《清实录·德宗景皇帝实录》","《（光绪）东华录》","陈可冀主编《清宫医案研究》所收光绪帝脉案"], tags: ["光绪之死","摄政王","宣统"] }, related: ["cn--1908--i02", "cn--1911--p02"] },
  { id: "cn--1908--e01", track: "cn", year: 1908, yearApprox: false, dim: "economy", weight: 3, title: "汉冶萍公司之合", summary: "铁厂、铁矿与煤矿合为一公司。", detail: { background: "汉阳铁厂自张之洞创设以来以煤、矿不相属而费重，萍乡之煤、大冶之铁皆待运，官督商办之弊积于借款与报销。", process: "1908年冬以汉阳铁厂、大冶铁矿、萍乡煤矿合为汉冶萍煤铁厂矿有限公司，去官督商办之名而改为商办，招集股本，以盛宣怀任经理，炉座、轨路之费仰于借款，向日商所借之款以铁砂、生铁抵偿，年限与数量累次展改，各册所载出入较大。", impact: "此为东亚未有之铁厂，而厂之借款与抵债之约使政府与会社之界不清，1913年以后借据累增，矿石出口之价与数皆为交涉之事，论者以汉冶萍之局为民国初年铁矿与钢价之争执所自出；公司之股票则随上海之市面而涨落，1910年风潮中亦大折其值。", figures: ["盛宣怀","张之洞"], place: "湖北汉阳、大冶，江西萍乡", state: "清", sources: ["《（光绪）东华录》","盛宣怀《愚斋存稿》","郭廷以《近代中国史纲》"], tags: ["汉冶萍","煤铁","公司"] }, related: ["cn--1908--i02", "cn--1910--e01"] },
  { id: "cn--1908--i02", track: "cn", year: 1908, yearApprox: false, dim: "institution", weight: 3, title: "钦定宪法大纲与筹备清单", summary: "大纲以君上之权居首，九年而毕筹备。", detail: { background: "自丙午宣布仿行宪政，宪政编查馆主其成，考察各国宪法而归本于大权不下移，草定者再易而后上。", process: "1908年《钦定宪法大纲》颁行，凡二章二十有三条，首列君上大权而以后附臣民权利义务，同时下逐年筹备事宜之清单，以九年为限，自1908年至宣统八年而毕，所先者为谘议局、新官制、司法之独立与户口、财产之清丈；《谘议局章程》亦于其年颁行。", impact: "大纲以宪法之名而著君上之权，立宪诸绅因此谓其非所以限君也，请愿国会之议遂以是起；筹备之清单逐年考成，各省之谘议局与清理财政皆以次而举，然1910年请愿缩定期限，1911年以内阁与十九信条应之，九年之程未半而局已变。", figures: ["载泽","端方","汪荣宝"], place: "京师", state: "清", sources: ["《钦定宪法大纲》，见《清末筹备立宪档案史料》","《（光绪）东华录》","刘锦藻《清朝续文献通考》"], tags: ["钦定宪法大纲","筹备清单","九年"] }, related: ["cn--1906--p01", "cn--1910--p01"] },
  { id: "cn--1909--p01", track: "cn", year: 1909, yearApprox: false, dim: "politics", weight: 4, title: "摄政王罢袁世凯", summary: "回籍养疴之命一下，北洋失其主。", detail: { background: "两宫之崩前后，袁世凯以病不预闻，而北洋将吏多出其门，戊申、己酉之际又尝以一言忤摄政王，去之与留皆为中枢之大计。", process: "1909年1月（宣统元年十二月）以摄政王命下谕，谓袁世凯现患足疾宜加调理，着开缺回籍养疴，其练兵处与北洋之事务归陆军部与度支部，段祺瑞、冯国璋诸人在职而无所禀命；袁氏归彰德，于洹上村治田，而北洋之将时往省视，报馆言其出入者不绝。", impact: "一谕而北洋之兵权散，中枢之任事者无如袁氏之习其事者，1911年秋鄂事既起，起用之请出于同一之门，进退遂为南北交迫之局；论者每以去袁一事为清室自撤其藩之始，亦谓辛亥以后北方之局即伏于此冬。", figures: ["载沣","袁世凯","段祺瑞"], place: "京师、河南彰德", state: "清", sources: ["《宣统政纪》","刘锦藻《清朝续文献通考》","郭廷以《近代中国史纲》"], tags: ["摄政王","袁世凯","北洋"] }, related: ["cn--1908--p01", "cn--1911--p02"] },
  { id: "cn--1909--i01", track: "cn", year: 1909, yearApprox: false, dim: "institution", weight: 3, title: "各省谘议局之开会", summary: "绅与商始有议事之堂。", detail: { background: "章程颁而选举之格以定，凡男女之别、财产、学历与地方之年皆入选格，各省筹办处择议员之额而行事。", process: "1909年秋（十月）各省谘议局同时开幕议事，议员以初选复选之法而出，妇女、无产与不识字者不与，江苏、浙江、湖北、湖南诸局开会之日以地方之学款、租股与自治之费相质，公推正、副议长，议决之案呈于督抚，督抚得奏请解散而须重选；各省之局复联为一会，互通电问。", impact: "谘议局非议院而以议事为习，绅商自此有公开之地，其议学款、议路款、议预算者直逼督抚，1910年请愿国会之即以局中人为骨干；地方之自治、警政与实业之款因此有可稽核之名，而论者亦谓清室之亡不在会党之起而在议事之堂已成。", figures: ["张謇","汤寿潜","蒲殿俊"], place: "江苏、浙江、湖北、湖南各省", state: "清", sources: ["《谘议局章程》，见《清末筹备立宪档案史料》","《（宣统）政纪》","张朋园《立宪派与辛亥革命》"], tags: ["谘议局","选举","绅商"] }, related: ["cn--1907--i02", "cn--1910--p01"] },
  { id: "cn--1909--i02", track: "cn", year: 1909, yearApprox: false, dim: "institution", weight: 2, title: "清理财政之局", summary: "各省始有预算与报部之册。", detail: { background: "外债、赔款与新政之费皆出于摊派，出入之册多不相应，部库与省库之分界不明，清理之议起于度支部。", process: "1909年度支部定《清理财政章程》，于各省设清理财政局，会同城与藩司核其出入，分门别类，编为岁入、岁出之册，限年报部，并订国库金之则与官银钱号之稽；各省之捐、之租股与学款、警款始有可稽之数，其不报与报而不符者亦多。", impact: "此为地方财政有预算之名之始，谘议局之所以能议本省之出入者即赖此册，而部、省两方因此更见其相胜：中央欲收其款，各省以任事者自居；论清末财政之不可为者谓清丈、预算之成适在鼎革之前二年，其功未及见而其效已启。", figures: ["载泽","绍英"], place: "京师与各省", state: "清", sources: ["《清末筹备立宪档案史料》","《宣统政纪》","刘锦藻《清朝续文献通考》"], tags: ["清理财政","预算","度支部"] }, related: ["cn--1909--i01", "cn--1911--p01"] },
  { id: "cn--1909--s01", track: "cn", year: 1909, yearApprox: false, dim: "science", weight: 3, title: "京张铁路之告成", summary: "自募款、自勘工之路二年而成。", detail: { background: "京张之议起于关内外铁路之余利可给工费，外人以地势险远谓中国工程师必不能为，工部之任专归华人。", process: "1909年秋京张铁路全线告成，自丰台达张家口，凡四百余里，越关沟、穿五桂头诸洞，于青龙桥设折返之线、以两机相推而上；工费较原估为节（所省之数各册记载出入较大），测量、记账之文皆由工程处自定，詹天佑总其成。", impact: "此路成而华人自建干路之议遂张，各省商办之路以是益信其可，工程、测量之人才亦以路事而练；其后民国之路政与工程学会之称述京张者，皆以是路为中国工程师自立之证，而此路所用之款与外债无涉，尤为时论所重。", figures: ["詹天佑"], place: "直隶丰台至张家口", state: "清", sources: ["詹天佑《京张铁路工程纪略》","金士宣、徐文述《中国铁路发展史》","《（宣统）政纪》"], tags: ["京张铁路","工程师","自建"] }, related: ["cn--1905--s01", "cn--1909--i02"] },
  { id: "cn--1910--p01", track: "cn", year: 1910, yearApprox: false, dim: "politics", weight: 4, title: "国会请愿之役", summary: "三至京师，得缩定期限之谕。", detail: { background: "谘议局既成，各省之绅以九年之预备为太久，谓非有国会则财政、铁路诸事无可取决，请愿之议起于上海、东京之立宪派诸报。", process: "1910年1月请愿代表至京师，以速开国会为请，不获；6月各省代表复至，孙洪伊等主之，都察院为之代奏，谕以筹备未就绪；10月第三次之请愿益迫，十七省代表连日递呈，议将久留以待，11月初朝廷下谕，谓议院之开著缩小年限，定为宣统五年，并命请愿代表即日散归。", impact: "三次请愿而得提前三年之谕，立宪派以是分为两途，其缓进者犹望内阁之先成，其急进者谓奏请之无效，士之由请愿而转向革命者自此益众；且谕之与请愿相始终，使各省谘议局成一永久之政治机关，1911年之皇族内阁与十九信条皆在此局中。", figures: ["孙洪伊","张謇","汤化龙","蒲殿俊"], place: "京师、上海、各省谘议局", state: "清", sources: ["《清末筹备立宪档案史料》","《时报》1910年原载","张朋园《立宪派与辛亥革命》"], tags: ["国会请愿","谘议局","立宪派"] }, related: ["cn--1908--i02", "cn--1911--p01"] },
  { id: "cn--1910--p02", track: "cn", year: 1910, yearApprox: false, dim: "politics", weight: 3, title: "银桥之炸与汪兆铭之狱", summary: "谋炸摄政王，狱成而免死。", detail: { background: "自同盟会数起失败，一部分人以暗杀为可以振人心、可以毙元恶，汪兆铭、黄复生等在东京谋先及于中国之亲贵。", process: "1910年3月底炸弹发觉于银桥之侧，4月汪兆铭、黄复生先后被捕，赵秉钧鞫之，汪兆铭以供词自陈其志；法部以谋逆大狱按律当凌迟，改判永远监禁，1911年冬赦出。", impact: "谋炸中枢之亲贵而得不死之刑，此出于载沣之自命宽大，而少年之士读其供词者转视为成仁，革命之名为之益重；狱中与《民立报》诸报相为声气，辛亥之冬释狱而后汪兆铭之名已居党内之要地，论者谓此案于人心之向背所关甚大。", figures: ["汪兆铭","黄复生","载沣","赵秉钧"], place: "京师", state: "清", sources: ["中国近代史资料丛刊《辛亥革命》","冯自由《革命逸史》","《宣统政纪》"], tags: ["暗杀","汪兆铭","庚戌"] }, related: ["cn--1910--c01", "cn--1909--p01"] },
  { id: "cn--1910--i01", track: "cn", year: 1910, yearApprox: false, dim: "institution", weight: 3, title: "圆两之争与币制则例", summary: "以圆为单位之议始定。", detail: { background: "国币之称两与圆久相持，各省之龙洋、外国之站人与鹰洋并行，丁漕、捐税以两计而市肆以圆计，部、省之意亦不尽同。", process: "1910年3月度支部奏定《币制则例》，准铸大金、银、铜三种国币，以银币一圆为主，重七钱二分，其下为五角、二角、一角，停两之用于新币，而各省之旧铸与民间之用两者未能即改，1914年之《国币条例》仍循此格。", impact: "自是圆之名入于国币之制，而两之俗尚行于税收与钱庄，二者之折合遂为市面与官册之争，论近世币制者多以则例之定为圆两递嬗之枢纽，1933年废两改元之议亦以是为其根；币制之统一虽未即成，然单位之定已为民国以后之成案。", figures: ["载泽","绍英"], place: "京师、天津造币总厂", state: "清", sources: ["《币制则例》，见《清末筹备立宪档案史料》","《宣统政纪》","彭信威《中国货币史》"], tags: ["币制则例","圆两之争","国币"] }, related: ["cn--1909--i02", "cn--1910--e01"] },
  { id: "cn--1910--e01", track: "cn", year: 1910, yearApprox: false, dim: "economy", weight: 3, title: "上海橡皮股票之风潮", summary: "胶市一跌，钱庄与洋行同覆。", detail: { background: "自南洋种胶之利兴，沪上以橡胶公司之名招股者数十家，股票之价数月而倍增，钱庄以票拆借于洋行，洋行又转贷于公司。", process: "1910年夏秋间外洋胶价低落，沪上之橡皮股票随以大跌，正元、兆康、谦余诸洋行先后宣告亏空，其数以银计至数百万两（各册多寡不一），源丰润、义善源相继倒，钱庄之停业与倒闭者相属，市面之拆息骤贵，商务、田房皆滞，两江与租界之当局议以公款维持。", impact: "一市之股风能使沿江之钱庄俱困，此为中国金融史上第一次以股票为潮之案，凡公司、股票、拆借与钱庄之险皆见于此；上海之商务因此年之损而迟回不复，1911年之市面与辛亥革命时之财政困难，皆与此案相续而言。", figures: ["周金箴"], place: "上海", state: "清", sources: ["《时报》《申报》1910年原载","《上海钱庄史料》，中国人民银行上海市分行编","《宣统政纪》"], tags: ["橡皮股票","钱庄","市面风潮"] }, related: ["cn--1908--e01", "cn--1912--e01"] },
  { id: "cn--1910--e02", track: "cn", year: 1910, yearApprox: false, dim: "economy", weight: 2, title: "南洋劝业会之开", summary: "一会以陈全国之物产。", detail: { background: "自商部劝工之设、各省劝业会场之立，办会之议起于两江，以开风气和实业为指，筹款与征集之件历两年而后备。", process: "1910年夏南洋劝业会开于江宁，设馆分任实业、教育、农业与对外之品，各省之制造与南洋侨商之货并陈，会期数月，参观者以数十万计（会所自载之数与报馆所记出入较大），并设审查之所评其等第。", impact: "此为以全国为范围之第一次劝业会，其章程、分区与审查之法皆民国以后展览会之所本；一会以劝工与奖实业相并，士绅因之结为公司与商会之网，论江南实业与地方自治之关系者每举一会为证。", figures: ["张謇","端方"], place: "江苏江宁", state: "清", sources: ["《张謇全集》","《时报》1910年原载","《（宣统）政纪》"], tags: ["南洋劝业会","实业","展览"] }, related: ["cn--1906--e01", "cn--1910--e01"] },
  { id: "cn--1910--d01", track: "cn", year: 1910, yearApprox: false, dim: "disaster", weight: 3, title: "满洲肺鼠疫之起", summary: "疫起于东省铁路，隔离与焚尸并行。", detail: { background: "1910年冬自俄境与东清铁路沿线之猎户、矿工传染而南，傅家甸与哈尔滨之市面首当其冲，地方之医无治此之法。", process: "1910年11月起疫由满洲里、哈尔滨南犯长春、奉天，死者日以数百人，清廷命伍连德赴哈主持防疫，寻任东三省防疫总医官，分区隔离、设医院与防疫所、验尸焚尸，并用口罩与断交通之法，至1911年4月而止，疫死之数自册报与海关之报告合计约六万人（各方统计多寡不一），1911年4月在奉天开万国鼠疫研究会。", impact: "以一疫而得防疫之制与海关、地方报疫情之章程，东三省之公共卫生自是设局，1911年后各省之防疫所与检疫之局皆仿此；而疫起于铁路沿线，中日俄三方之交涉随之而起，论者以是役为中国以近世医法办大疫之始。", figures: ["伍连德","施肇基"], place: "黑龙江、吉林、奉天", state: "清", sources: ["《（宣统）政纪》","中国海关《十年报告（1902—1911）》所载疫事","《申报》1910—1911年原载"], tags: ["满洲鼠疫","防疫","公共卫生"] }, related: ["cn--1907--i01", "cn--1910--i01"] },
  { id: "cn--1910--c01", track: "cn", year: 1910, yearApprox: false, dim: "culture", weight: 2, title: "《民立报》创刊", summary: "一报起于沪上，为辛亥年言论之府。", detail: { background: "己酉、庚戌之间，上海之报以立宪与革命分涂，《国风报》《时报》主渐进，少年之士别求一快其意者。", process: "1910年10月于右任等在上海创《民立报》，邵力子主笔政，取材料于东京之同盟会与各省之谘议局，于暗杀之狱、铁路之案与外交诸件多所论难，销数日广，馆中且为留东学子与党人往来之地。", impact: "此报与《天铎》《时报》《申报》诸纸并峙，而言论之锐独出，辛亥武昌事起后之各省响应，报馆之通电与议论为多，论民国初年报界与政争之关系者以是报为其枢纽之一。", figures: ["于右任","邵力子"], place: "上海", state: "清", sources: ["《民立报》原刊（1910—1913）","戈公振《中国报学史》","《（宣统）政纪》"], tags: ["民立报","报界","于右任"] }, related: ["cn--1911--p02", "cn--1910--p02"] },
  { id: "cn--1911--p01", track: "cn", year: 1911, yearApprox: false, dim: "politics", weight: 5, title: "铁路国有之诏与保路之争", summary: "干路收归国有，川、鄂、湘三省之风潮遂起。", detail: { background: "各省商办之路款绌而工缓，邮传部以借款成路为议，四国银行团之湖广路债亦于是年议定，川省之租股已入民而路未成一尺。", process: "1911年5月朝廷下铁路干路国有之诏，旋与英、法、德、美四国银行团订湖广铁路借款之约，六百万镑、五厘、四十年，以鄂、湘两省之厘金与捐税为抵；川、鄂、湘、粤四省议设保路同志会，湖南、湖北以绅商为多，四川之荣县、成都继以抗租、抗粮为争，8月督署捕其首领，9月2日成都请愿之众开门而出，巡防营开枪，死者数十人（各册多寡不一），议者哗然。", impact: "朝廷以未尝经民意之命收民间已认之款，各省因此并起，四川之兵东调而武昌之防空虚，论辛亥革命之机会者多以保路一事为其先声；九月成都之案与湖北新军之谋恰相值，此事之起在其后一月。", figures: ["盛宣怀","端方","蒲殿俊","罗纶"], place: "京师、成都、长沙、武昌", state: "清", sources: ["《湖广铁路借款契约》，见王铁崖编《中外旧约章汇编》","《（宣统）政纪》","《四川保路同志会报告》，见中国近代史资料丛刊《辛亥革命》"], tags: ["铁路国有","保路","四国借款"] }, related: ["cn--1911--p02", "cn--1906--e01"] },
  { id: "cn--1911--p02", track: "cn", year: 1911, yearApprox: false, dim: "politics", weight: 5, title: "武昌之役与军政府之立", summary: "工程营一夕举事，十八星旗立于黄鹤楼。", detail: { background: "文学社、共进会两团体在湖北新军中结纳数年，名册已具而期日未定，孙武在汉造炸弹失事，名册入官，举事者以仓卒决之。", process: "1911年10月10夜（八月十九日）武昌工程营首举，楚望台军械局为据，翌晨城陷，黎元洪被推为都督，湖北军政府立，宣布以都督名义行文各省，宣布国号为中华民国，文告用黄帝纪元，其后各府州次第响应，汉阳、汉口相持月余。", impact: "一城之变而十五省相继宣布独立（各省起事之先后与名义，各册多寡不一），中枢不能以兵制之，清室之命脉至此已断；武昌之役所以异于乙巳、庚戌诸役者，在新军之成伍、谘议局之在城、而国库之无款三者俱会于此年。", figures: ["黎元洪","蒋翊武","孙武","汤化龙"], place: "湖北武昌、汉阳、汉口", state: "清", sources: ["《武昌首义资料》，见中国近代史资料丛刊《辛亥革命》","《（宣统）政纪》","《民立报》1911年原载"], tags: ["武昌起义","湖北军政府","辛亥"] }, related: ["cn--1911--p01", "cn--1911--p03"] },
  { id: "cn--1911--p03", track: "cn", year: 1911, yearApprox: false, dim: "politics", weight: 4, title: "各省宣布独立之局", summary: "一月之间十五省去其督抚。", detail: { background: "武昌事起而朝廷调北洋之军南下，同时各省之谘议局、新军与商会互电声问，中枢之令不出于畿辅。", process: "自10月下旬湖南、陕西应之，江西、山西、云南、贵州、江苏、浙江、广西、安徽、福建、广东、山东、四川相继以独立或光复为文告，或举旧吏、或推军人、或咨议局与商会共议而改署，旗色与印文不一；上海于11月3日光复，苏、浙都督之府并于是一带之税与借款为之移。", impact: "省之自立既成事实，清廷之命已不能行于南方，袁世凯之起用与北洋军之进止于是有左右轻重之势；而各省之都督各为其政，财政、军械不相统一，此民国初年之局，其端即在此一月之中。", figures: ["程德全","汤寿潜","唐继尧","李烈钧"], place: "湖南、陕西、云南、江苏、浙江、上海", state: "清", sources: ["中国近代史资料丛刊《辛亥革命》","《民立报》1911年原载","《（宣统）政纪》"], tags: ["各省独立","都督","辛亥"] }, related: ["cn--1911--p02", "cn--1912--p01"] },
  { id: "cn--1911--p04", track: "cn", year: 1911, yearApprox: false, dim: "politics", weight: 3, title: "内阁之改与十九信条", summary: "皇族之内阁先成，十九信条后出而无可挽。", detail: { background: "预备立宪之清单以成立内阁为先着，而摄政王以亲贵任兵、财二端，各省谘议局之请愿又以速开国会相逼。", process: "1911年5月8日定内阁之制，以庆亲王奕劻为内阁总理大臣，十三大臣中满人居其九、皇族居七人，议者哗然，谓之皇族内阁；武昌既起，11月初（九月十三日）遂命袁世凯为内阁总理大臣，同时颁《十九信条》，以宪法之大纲归国会议定，而大权之归与皇室之地位仍存其旧。", impact: "内阁之名与十九信条皆为事后之应，立宪派之望于是渐穷，各省之独立不因信条而止；论清末立宪之成败者多即此五月、九月两诏断之，谓其始也以名实不相副而失士心，其终也虽欲让权而无所与。", figures: ["奕劻","载沣","袁世凯"], place: "京师", state: "清", sources: ["《十九信条》，见《清末筹备立宪档案史料》","《（宣统）政纪》","刘锦藻《清朝续文献通考》"], tags: ["皇族内阁","十九信条","立宪"] }, related: ["cn--1910--p01", "cn--1911--p02"] },
  { id: "cn--1911--m01", track: "cn", year: 1911, yearApprox: false, dim: "military", weight: 3, title: "阳夏之役与汉口之火", summary: "北军南下，汉口市经火而残。", detail: { background: "武昌既据，清廷起袁世凯于籍，以冯国璋攻其北，段祺瑞继之，北洋之军由京汉路南下，而汉阳之兵工厂与汉口之商市为其所必争。", process: "1911年10月下旬至11月，清军攻刘家庙、滠口与汉口，民军拒守者累日，汉口市街经火而商屋尽，所失之屋与货值，商会与保险之册、后来之研究其说不一；11月下旬汉阳亦不能守，两岸以炮相问而各无大进。", impact: "阳夏一役使军事之胜负与谈判之机会并至，武昌之能支以汉、阳之相持为其蔽，袁世凯之不以全力进取、而言和之议遂开，南京与武汉之代表、唐绍仪与伍廷芳之南北会议皆以是而移。", figures: ["冯国璋","段祺瑞","黄兴","黎元洪"], place: "湖北汉口、汉阳、滠口", state: "清", sources: ["《阳夏战争》，见中国近代史资料丛刊《辛亥革命》","《（宣统）政纪》","《民立报》1911年原载"], tags: ["阳夏之役","汉口火","南北相持"] }, related: ["cn--1911--p02", "cn--1911--p04"] },
  { id: "cn--1911--i01", track: "cn", year: 1911, yearApprox: false, dim: "institution", weight: 3, title: "临时政府组织大纲之议", summary: "各省代表聚会于汉、宁，先定政府之形。", detail: { background: "独立之省各都督府并立而无所统，代表之会先起于上海，移于武昌，再移于南京，须一约法以定其联合之名。", process: "1911年11月各省都督府代表联合会开会于上海，寻移汉口，议定《临时政府组织大纲》以总统制为纲，设各部与参议院，都督每省以三人为限、各投一票，12月上旬各省代表选举临时大总统之议备，1912年元旦政府以是告成。", impact: "此大纲为共和政体之第一部成文之组织法，其总统制与内阁制之争即伏其中，1912年3月之《临时约法》改而取责任内阁之说，为此后府院之争与约法存废诸案之所自出。", figures: ["温宗尧","伍廷芳","谭人凤"], place: "上海、汉口、南京", state: "民国", sources: ["《临时政府组织大纲》，见《（民国）法规汇编》","中国近代史资料丛刊《辛亥革命》","《民立报》1911年原载"], tags: ["组织大纲","各省代表","总统制"] }, related: ["cn--1912--p01", "cn--1912--i01"] },
];
